class Solution:
    def twoSum(self, nums: List[int], target: int) -> List[int]:
        diffs = {}

        for i,e in enumerate(nums):
            diffs[target - e] = i

        for i in range(len(nums)):
            if nums[i] in diffs:
                if diffs[nums[i]] != i:
                    return sorted([diffs[nums[i]], i])

