from collections import defaultdict

class Solution:
    def findErrorNums(self, nums: List[int]) -> List[int]:
        d = defaultdict(lambda:0)
        for n in nums:
            d[n] += 1
        out = [-1, -1]
        for k,v in d.items():
            if v == 2:
                out[0] = k
        out[1] = list(set(range(1,len(nums)+1)) - set(nums))[0]
        return out

from math import gcd

class Solution:
    def union(self, a, b):
        # combine the components of these two nodes
        a_parent = self.find(a)
        b_parent = self.find(b)

        if a_parent == b_parent:
            return

        # put smaller under larger
        if self.size[a_parent] > self.size[b_parent]:
            # a is bigger than b, put b under a
            self.parent[b_parent] = a_parent
            self.size[a_parent] += self.size[b_parent]
        else:
            # b is bigger than a, put a under b
            self.parent[a_parent] = b_parent
            self.size[b_parent] += self.size[a_parent]



    def find(self, a):
        # find parent of this node
        while self.parent[a] != a:
            a = self.parent[a]
        return a

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def areConnected(self, n: int, threshold: int, queries: List[List[int]]) -> List[bool]:
        # edge case
        if threshold == 0:
            return [True] * len(queries)

        road_exists = lambda x, y : gcd(x,y) > threshold

        # offset size and parent lists by 1 to make indexing work
        self.parent = [-1] + [i for i in range(1,n+1)]
        self.size = [-1] + [1 for i in range(1,n+1)]

        for i in range(threshold,n):
            for j in range(i+1,n+1):
                if road_exists(i,j):
                    self.union(i,j)

        out = []

        for (start, end) in queries:
            connected = self.connected(start, end)
            out.append(connected)

        return out

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        best = 0
        left = 0

        contents = set()

        for right in range(len(s)):
            while s[right] in contents:
                contents -= {s[left]}
                left += 1
            contents.add(s[right])
            best = max(best, right - left + 1)


        return best

