class Solution:
    def romanToInt(self, s: str) -> int:
        d = {
            'I' : 1,
            'V' : 5,
            'X' : 10,
            'L' : 50, 
            'C' : 100,
            'D' : 500,
            'M' : 1000
        }

        idx = 0
        total = 0
        while idx < len(s):
            curr = s[idx]
            if idx + 1 < len(s):
                next = s[idx+1]
            else:
                next = False
            if next and curr == next:
                total += d[curr]
            elif next and d[curr] < d[next]:
                total += d[next] - d[curr]
                idx += 1
            else:
                total += d[curr]
            idx += 1
        return total

class Solution:
    def longestCommonPrefix(self, strs: List[str]) -> str:
        end = len(strs[0])
        prev = strs[0]
        for s in strs[1:]:
            # decrease overlap index
            while not s.startswith(prev[:end]):
                end -= 1
        return strs[0][:end]

class Solution:
    def isValid(self, s: str) -> bool:
        stack = []
        open = '([{'
        closed = ')]}'
        for c in s:
            if c in open:
                stack.append(c)
            elif c in closed:
                if not stack:
                    return False
                if open.find(stack[-1]) == closed.find(c):
                    stack.pop()
                else:
                    return False
            else:
                return False
        return not stack

class Solution:
    def helper(self, h1, h2, acc):
        if h1 is None and h2 is None:
            return acc
        if h2 is None:
            acc.next = h1
            return self.helper(h1.next, None, h1)
        if h1 is None:
            acc.next = h2
            return self.helper(None, h2.next, h2)
        if h1.val <= h2.val:
            acc.next = h1
            return self.helper(h1.next, h2, h1)
        else:
            acc.next = h2
            return self.helper(h1, h2.next, h2)

    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:
        if list1 is None:
            return list2
        if list2 is None:
            return list1

        t1 = list1
        t2 = list2

        if list1.val < list2.val:
            head = list1
            t1 = head.next
        else:
            head = list2
            t2 = head.next

        self.helper(t1, t2, head)

        return head

class Solution:
    def removeDuplicates(self, nums: List[int]) -> int:
        # use `del list[index]` to remove that item inplace
        prev = nums[0]
        idx = 1
        n = len(nums)
        while idx < n:
            if nums[idx] == prev:
                del nums[idx]
                n -= 1
            else:
                prev = nums[idx]
                idx += 1

        return n

class Solution:
    def removeElement(self, nums: List[int], val: int) -> int:
        n = len(nums)
        idx = 0
        while idx < n:
            if nums[idx] == val:
                del nums[idx]
                n -= 1
            else:
                idx += 1
        return n

