class Solution:
    def searchInsert(self, nums: List[int], target: int) -> int:
        # edge cases
        if target <= nums[0]:
            return 0
        if target > nums[-1]:
            return len(nums)
        if target == nums[-1]:
            return len(nums) - 1

        # binary search
        lo, hi = 0, len(nums)-1
        mid = (lo + hi) // 2
        # keep track of prev val to make logic easier
        # if detect repeat then just return hi val (because target still between lo and hi)
        prev = (lo, mid, hi)
        while nums[lo] < target < nums[hi]:
            mid = (lo + hi) // 2
            # print(lo, mid, hi)
            if target < nums[mid]:
                hi = mid
            elif target > nums[mid]:
                lo = mid
            else: # target == mid
                return mid
            if prev == (lo, mid, hi):
                return hi
            else:
                prev = (lo, mid, hi)

        if target == nums[lo]:
            return lo
        if target == nums[hi]:
            return hi

class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        def valid(group):
            group = [c for c in group if c != '.']
            # contains elements outside 1..9
            if set(group) - set('123456789'):
                return False
            # contains dupes
            if len(set(group)) < len(group):
                return False
            return True

        # transpose to get columns
        columns = [[board[j][i] for j in range(len(board))] for i in range(len(board))]

        # get 3x3 boxes
        boxes = [[[] for _ in range(3)] for _ in range(3)]
        for r in range(len(board)):
            for c in range(len(board)):
                boxes[r // 3][c // 3].append(board[r][c])

        print(boxes)

        good = True
        good = good and all(valid(row) for row in board)
        good = good and all(valid(col) for col in columns)
        for row in boxes:
            for box in row:
                good = good and valid(box)

        return good

