class Solution:
    def mySqrt(self, x: int) -> int:
        # bin search
        def search(lo, hi, target):
            mid = (lo + hi) // 2
            # if lo == hi:
            #     return lo
            if lo ** 2 < target < (lo + 1) ** 2:
                return lo
            if target > mid ** 2:
                return search(mid, hi, target)
            elif target < mid ** 2:
                return search(lo, mid, target)
            else: # somehow target = mid ** 2
                return mid

        # max is 2 ** 31 - 1 so use that as upper bound
        return search(0, 2 ** 31 - 1, x)

class Solution:
    def climb(self, n):
        if n in self.ways:
            return self.ways[n]
        if n == 0:
            return 0
        if n == 1:
            return 1
        if n == 2:
            return 2
        ways = self.climb(n-1) + self.climb(n-2)
        self.ways[n] = ways
        return ways

    def climbStairs(self, n: int) -> int:
        self.ways = {}
        return self.climb(n)

class Solution:
    def deleteDuplicates(self, head: Optional[ListNode]) -> Optional[ListNode]:
        def helper(head):
            if head is None or head.next is None:
                return
            if head.next.val == head.val:
                head.next = head.next.next
                helper(head)
            else:
                helper(head.next)

        helper(head)
        return head

class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        max_profit = 0
        min_price = prices[0]
        for i in prices[1:]:
            this_profit = i - min_price
            if this_profit > max_profit:
                max_profit = this_profit

            if i < min_price:
                min_price = i

        return max_profit

class Solution:
    def hasCycle(self, head: Optional[ListNode]) -> bool:
        if head is None:
            return False
        onestep = head
        twostep = head
        if head.next is None:
            return False
        if head.next.next is None:
            return False
        twostep = head.next.next
        while onestep != twostep:
            onestep = onestep.next
            if onestep is None:
                return False
            twostep = twostep.next
            if twostep is None:
                return False
            twostep = twostep.next
            if twostep is None:
                return False
        return True

class Solution:
    def rob(self, nums: List[int]) -> int:
        best_choices = [-1]*(len(nums)-2) + [max(nums[-2:])] + [nums[-1]] 

        def get_nonadj_choices(i):
            # if we've already calculated this, use that result
            if best_choices[i] != -1:
                return best_choices[i]
            # if we're at the end, just take the max
            if len(nums[i:]) <= 2:
                return max(nums[i:])

            # `take_first` and `take_second` are our options from this index
            # that we will be weighing against each other

            if i + 2 >= len(nums):
                take_first = nums[i]
            else:
                take_first = nums[i] + get_nonadj_choices(i+2)

            if i + 3 >= len(nums):
                take_second = nums[i+1]
            else:
                take_second = nums[i+1] + get_nonadj_choices(i+3)

            # typical dp - maximize based on our options
            best_choices[i] = max(take_first, take_second)

            return best_choices[i]

        return get_nonadj_choices(0)

