import random

class RandomizedSet:

    def __init__(self):
        self.dict = {}
        self.list = []

    def insert(self, val: int) -> bool:
        if val not in self.dict:
            self.dict[val] = len(self.list)
            self.list.append(val)
            return True
        return False

    def remove(self, val: int) -> bool:
        if val in self.dict:
            # swap last with this one in list
            end = self.list[-1]
            val_index = self.dict[val]
            self.dict[end] = self.dict[val]
            self.list[val_index] = end
            del self.dict[val]
            self.list.pop()
            return True
        return False

    def getRandom(self) -> int:
        return random.choice(self.list)

class Solution:
    def helper(self, i,j):
        if (i,j) in self.minsum:
            return self.minsum[i,j]
        if i + 1 == self.n:
            self.minsum[i,j] = self.matrix[i][j]
            return self.matrix[i][j]
        options = [self.helper(i+1, j)]
        if j > 0:
            left = i+1, j-1
            options.append(self.helper(*left))
        if j < self.n-1:
            right = i+1, j+1
            options.append(self.helper(*right))
        minsum = min(options) + self.matrix[i][j]
        self.minsum[i,j] = minsum
        return minsum

    def minFallingPathSum(self, matrix: List[List[int]]) -> int:
        self.minsum = {} # (i,j) => min sum from matrix[i][j]

        self.matrix = matrix

        self.n = len(matrix)

        for row in range(self.n):
            for col in range(self.n):
                self.helper(row, col)

        minval = 1e100
        for (r,c),v in self.minsum.items():
            if r == 0:
                if v < minval:
                    minval = v

        # print(self.minsum)

        return minval

