from itertools import pairwise

class Solution:
    def checkStraightLine(self, coordinates: List[List[int]]) -> bool:
        # idea - straight line if slope same between all points
        prev_slope = None
        for p1, p2 in pairwise(coordinates):
            x1, y1 = p1
            x2, y2 = p2
            if x1 == x2:
                slope = 'inf'
            else:
                slope = (y2 - y1)/(x2 - x1)
            if prev_slope is not None:
                if slope != prev_slope:
                    return False
            prev_slope = slope
        return True

class Solution:
    def kWeakestRows(self, mat: List[List[int]], k: int) -> List[int]:
        idx_mat = [(i,L) for i,L in enumerate(mat)] # add indices
        # sort with indices and give higher indices a bonus
        def f(t):
            i,L=t
            return sum(L) + (i/(len(mat) + len(mat[0])))
        sorted_mat = sorted(idx_mat, key=f)
        return [i for i,_ in sorted_mat[:k]]

class Solution:
    def countLargestGroup(self, n: int) -> int:
        sum_counts = {}
        for i in range(1,n+1):
            digit_sum = sum(int(c) for c in str(i))
            if digit_sum in sum_counts:
                sum_counts[digit_sum] += 1
            else:
                sum_counts[digit_sum] = 1
        largest_size = max(sum_counts.values())
        return list(sum_counts.values()).count(largest_size)

class Solution:
    def reverse(self, x: int) -> int:
        neg = x < 0
        rev = int(str(abs(x))[::-1])
        if neg: rev = -rev
        if rev > 2**31 - 1 or rev < -(2**31):
            return 0
        return rev

class Solution:
    def convert(self, s: str, numRows: int) -> str:
        rows = [[] for _ in range(numRows)]
        row = 0
        ascending = True
        for c in s:
            rows[row].append(c)
            if ascending:
                if row + 1 < numRows:
                    row += 1
                if row + 1 == numRows:
                    ascending = False
            else:
                if row - 1 > -1:
                    row -= 1
                if row == 0:
                    ascending = True

        out = ''
        for row in rows:
            out += ''.join(row)
        return out

from itertools import chain, combinations

def powerset(arr):
    return chain.from_iterable(combinations(arr, r) for r in range(len(arr)+1))

class Solution:
    def maxLength(self, arr: List[str]) -> int:
        def is_valid(subarr):
            s = ''.join(subarr)
            return len(s) == len(set(s))
        # try deleting certain elements
        maxlen = 0
        for choices in powerset(arr):
            if is_valid(choices):
                maxlen = max(maxlen, len(''.join(choices)))
        return maxlen

