class Solution:
    def pseudoPalindromicPaths (self, root: Optional[TreeNode]) -> int:
        def applyNumber(n : int, new : int):
            # parity-preserving application of `new` to `n`'s binary rep
            return n ^ (1 << (new - 1))

        def numOnes(n : int): 
            return bin(n).count('1')

        def is_pseudo_palindromic(n : int):
            return numOnes(n) <= 1

        # get all paths in bin tree
        totalPalindromic = 0
        def traverse(parities, head):
            nonlocal totalPalindromic
            updatedParities = applyNumber(parities, head.val)
            if head.left is None and head.right is None:
                # leaf node
                if is_pseudo_palindromic(updatedParities):
                    totalPalindromic += 1
                return
            if head.left:
                traverse(updatedParities, head.left)
            if head.right:
                traverse(updatedParities, head.right)

        traverse(0, root)
        return totalPalindromic

class Solution:
    def longestCommonSubsequence(self, text1: str, text2: str) -> int:
        matrix = [[0 for j in range(len(text1)+1)] 
                     for i in range(len(text2)+1)]

        for i,ei in enumerate(text2[::-1]):
            i = len(text2) - i - 1
            for j,ej in enumerate(text1[::-1]):
                j = len(text1) - j - 1
                if ei == ej: # same letter
                    matrix[i][j] = 1 + matrix[i+1][j+1]
                else:
                    matrix[i][j] = max(matrix[i+1][j], matrix[i][j+1])

        return matrix[0][0]

class Solution:
    def findPaths(self, m: int, n: int, maxMove: int, startRow: int, startColumn: int) -> int:
        numPaths = {} # (row, col, numMovesRemaining)
        mod = (10**9) + 7
        def outside(r, c):
            if r >= m or r < 0: return True
            if c >= n or c < 0: return True
            return False

        def helper(r, c, moves):
            if (r,c,moves) in numPaths:
                return numPaths[r,c,moves]
            if outside(r, c):
                return 1
            if moves == 0:
                return 0
            # left, right, up, down
            out = (
                helper(r, c-1, moves-1) +
                helper(r, c+1, moves-1) +
                helper(r-1, c, moves-1) +
                helper(r+1, c, moves-1)
            ) % mod
            numPaths[r, c, moves] = out
            return out

        return helper(startRow, startColumn, maxMove)

class Solution:
    def kInversePairs(self, n: int, k: int) -> int:
        mod = 10**9 + 7

        d = {}

        def f(n, k):
            if (n, k) in d:
                return d[n, k]

            if n == 0 and k >= 1:
                d[n, k] = 0
                return 0

            if k < 0:
                d[n, k] = 0
                return 0

            if k == 0:
                d[n, k] = 1
                return 1

            if k < n:
                out = f(n, k-1) + f(n-1, k) % mod
                d[n, k] = out
                return out
            else:
                out = f(n, k-1) + f(n-1, k) - f(n-1, k-n) % mod
                d[n, k] = out
                return out

        return f(n, k) % mod

