class Solution:
    def rangeSumBST(self, root: Optional[TreeNode], low: int, high: int) -> int:
        def dfs(root):
            if root is None: return 0
            out = root.val if low <= root.val <= high else 0
            return out + dfs(root.left) + dfs(root.right)
        return dfs(root)

