class Solution:
    def findMode(self, root: Optional[TreeNode]) -> List[int]:
        counts = {}
        def dfs(root):
            if root is None:
                return
            if root.val in counts:
                counts[root.val] += 1
            else:
                counts[root.val] = 1
            dfs(root.left)
            dfs(root.right)
        dfs(root)
        maxCount = max(list(counts.values()))
        return [val for val in counts if counts[val] == maxCount]

