class Solution:
    def numberOfMatches(self, n: int) -> int:
        d={}
        def f(n):
            if n<2:return 0
            if n==2:return 1
            if n in d:return d[n]
            if n%2:d[n]=(n-1)/2+f(1+(n-1)/2)
            else:d[n]=n/2+f(n/2)
            return d[n]
        return int(f(n))

