class Solution:
    def numSubmatrixSumTarget(self, matrix: List[List[int]], target: int) -> int:
        # https://www.youtube.com/watch?v=43DRBP2DUHg
        rows, cols = len(matrix), len(matrix[0])
        prefix_sums = [[0] * cols for _ in range(rows)]

        # submatrix prefix sums
        for r in range(rows):
            for c in range(cols):
                top = prefix_sums[r-1][c] if r > 0 else 0
                left = prefix_sums[r][c-1] if c > 0 else 0
                top_left = prefix_sums[r-1][c-1] if min(r,c) > 0 else 0
                # deal with double counting top left
                prefix_sums[r][c] = matrix[r][c] + top + left - top_left

        total_count = 0
        # use two pointers for row start and end and one pointer for col
        for r1 in range(rows):
            for r2 in range(r1, rows):
                count = {} # dict of { prefix sum : number seen }
                count[0] = 1
                for c in range(cols):
                    current_sum = prefix_sums[r2][c] - (prefix_sums[r1-1][c] if r1 > 0 else 0)
                    diff = current_sum - target
                    if diff in count:
                        total_count += count[diff]
                    if current_sum in count:
                        count[current_sum] += 1
                    else:
                        count[current_sum] = 1
        return total_count

