    def maxLengthBetweenEqualCharacters(self, s: str) -> int:
        if len(set(s)) == len(s):
            return -1
        d = {}
        for i,c in enumerate(s):
            if c in d:
                m,M = d[c]
                if i < m:
                    d[c] = (i,M)
                if i > M:
                    d[c] = (m,i)
            else:
