class Solution:
    def evalRPN(self, tokens: List[str]) -> int:
        def customRound(n):
            if n < 0: return ceil(n)
            return floor(n)
        stack = []
        ops = '+-*/'
        for t in tokens:
            if t in ops:
                b,a = stack.pop(), stack.pop()
                if t == '+': stack.append(a + b)
                elif t == '/': stack.append(customRound(a/b))
                elif t == '*': stack.append(a * b)
                elif t == '-': stack.append(a - b)
                else: raise Exception('idk what this is: ' + t)
            else:
                stack.append(int(t))
        return stack[-1]

