class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        # idea - stack of temperatures, if we find higher one then pop
        # and calculate index diff
        answer = [0] * len(temperatures)
        stack = [(temperatures[0], 0)] # stack has to be monotonic inc.
        for currIdx in range(1,len(temperatures)):
            curr = temperatures[currIdx]
            while stack:
                peek, peekIdx = stack[-1]
                if curr > peek:
                    answer[peekIdx] = currIdx - peekIdx
                    stack.pop()
                else:
                    break
            stack.append((curr, currIdx))
        # print(stack)
        # print(answer)
        return answer

