class Solution:
    def maxSumAfterPartitioning(self, arr: List[int], k: int) -> int:
        d = {0:0} # { length remaining : max sum }
        def maxArrPartitionSum(remainingArr):
            if len(remainingArr) in d:
                return d[len(remainingArr)]
            bestPartitionSum = 0
            for i in range(1,k+1):
                partitionSum = max(remainingArr[:i]) * len(remainingArr[:i])
                remainderSum = maxArrPartitionSum(remainingArr[i:])
                if partitionSum + remainderSum > bestPartitionSum:
