class PeekingIterator:
    def __init__(self, iterator):
        """
        Initialize your data structure here.
        :type iterator: Iterator
        """
        self.queued = None
        self.iterator = iterator

    def peek(self):
        """
        Returns the next element in the iteration without advancing the iterator.
        :rtype: int
        """
        if self.queued is not None:
            return self.queued
        else:
            self.queued = self.iterator.next()
            return self.queued

    def next(self):
        """
        :rtype: int
        """
        if self.queued is not None:
            out = self.queued
            self.queued = None
            return out
        else:
            return self.iterator.next()

    def hasNext(self):
        """
        :rtype: bool
        """
        return self.iterator.hasNext() or self.queued is not None

