class Solution:
    def firstBadVersion(self, n: int) -> int:
        lo, hi = 0, n
        def is_first_bad(idx):
            return ((not isBadVersion(idx-1)) or idx == 0) and isBadVersion(idx)
        mid = (lo + hi)//2
        while not is_first_bad(mid):
            if isBadVersion(mid):
                hi = mid
            else:
                lo = mid
            mid = (lo + hi)//2
            if mid == lo or mid == hi:
                if is_first_bad(lo): return lo
                if is_first_bad(hi): return hi
        return mid

