class Solution:
    def binaryTreePaths(self, root: Optional[TreeNode]) -> List[str]:
        def paths(root):
            out = []
            if root.left is not None:
                out += paths(root.left)
            if root.right is not None:
                out += paths(root.right)
            if out:
                return [str(root.val) + '->' + path for path in out]
            return [str(root.val)]
        return paths(root)

