    def minWindow(self, s: str, t: str) -> str:
        def valid(diffs): return all(v<=0 for v in diffs.values())
        def atEnd(r): return r >= len(s)
        def canMoveLeftPointer(diffs, s, l): return s[l] not in diffs or diffs[s[l]] < 0
        l,r = 0,0
        minWindow = ''
        minWindowLen = 1e300
        # precompute starting count diffs and update towards 0
        diffs = {}
        for c in t:
            if c in diffs: diffs[c] += 1
            else: diffs[c] = 1
        while True:
            while not (atEnd(r) or valid(diffs)):
                # update count diff to include new right char
                if s[r] in diffs: diffs[s[r]] -= 1
                r += 1
            while l < len(s) - 1 and canMoveLeftPointer(diffs, s, l):
                # update count diff to exclude left char
                if s[l] in diffs: diffs[s[l]] += 1
                l += 1
            if r-l < minWindowLen and valid(diffs):
                minWindow = s[l:r]
                minWindowLen = r-l
            if atEnd(r): return minWindow
            if s[l] in diffs: diffs[s[l]] += 1
            l += 1

