class Solution:
    def isSymmetric(self, root: Optional[TreeNode]) -> bool:
        # convert to arr and check if palindrome (add depth-based constant to make comparisons more accurate)
        def toArr(root, depth):
            if root.left is None and root.right is None: return [root.val + depth/10000]
            if root.left is None: return [root.val + depth/10000] + toArr(root.right, depth+1)
            if root.right is None: return toArr(root.left, depth+1) + [root.val + depth/10000]
            return toArr(root.left, depth+1) + [root.val + depth/10000] + toArr(root.right, depth+1)
        s = toArr(root, 0)
        return s == s[::-1]

