class Solution:
    def largestDivisibleSubset(self, nums: List[int]) -> List[int]:
        # note - Bron-Kerbosch algorithm is too slow here
        # instead use methodology similar to longest increasing subsequence
        nums.sort()
        dp = [[n] for n in nums] # dp[i] is longest seq that starts at and includes i
        for i in range(len(nums)):
            for j in range(i):
                if not nums[i] % nums[j] and len(dp[i]) < len(dp[j]) + 1:
                    dp[i] = dp[j] + [nums[i]]
        return max(dp, key=len)

class Solution:
