        for i in range(n-1):
            new_result = ''
            start, end = 0, 0
            while True:
                if end == len(result):
                    new_result += str(end-start) + result[start]
                    break
                elif result[start] == result[end]:
                    end += 1
                else:
                    new_result += str(end-start) + result[start]
                    start = end
            result = new_result
        return result

class Solution:
    def threeSum(self, nums: List[int]) -> List[List[int]]:
        with_indices = list(enumerate(nums))
        s = sorted(with_indices, key=lambda x:x[1])
        out = set()
        i = 0
        while i < len(s):
            target = -s[i][1]
            j,k = i+1,len(s)-1
            while j < k:
                guess = s[j][1] + s[k][1]
                if guess == target:
                    out.add(tuple(sorted([s[i][1], s[j][1], s[k][1]])))
                    j += 1; k -= 1
                elif guess > target:
                    k -= 1
                else: # guess < target:
                    j += 1
            i += 1
        return list(out)

