class Solution:
    def removeElements(self, head: Optional[ListNode], val: int) -> Optional[ListNode]:
        def removed(head):
            if head is None:
                return None
            if head.val == val:
                return removed(head.next)
            else:
                head.next = removed(head.next)
                return head
        return removed(head)

