class Solution:
    def jump(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return 0
        min_jumps = {len(nums) - 1 : 0}
        def min_jumps_to_end(idx):
            if idx in min_jumps: return min_jumps[idx]
            if nums[idx] == 0: return 1e300 # can't reach the end
            choices = range(idx + 1, min(idx + nums[idx] + 1, len(nums)))
            best_min_jumps = 1e200
            for choice in choices:
                this_min_jumps = 1 + min_jumps_to_end(choice)
                best_min_jumps = min(best_min_jumps, this_min_jumps)
            min_jumps[idx] = best_min_jumps
            return best_min_jumps
        return min_jumps_to_end(0)

