        i = 0
        while i < len(nums):
            if i >= 2 and prefix_sum > nums[i]:
                best_perimeter = max(best_perimeter, prefix_sum + nums[i])
            prefix_sum += nums[i]
            i += 1
        if best_perimeter == 0: return -1
        return best_perimeter

