        counts = {}
        for n in nums:
            if n in counts:
                counts[n] += 1
            else:
                counts[n] = 1
        # translate counts into 2d array
        out = []
        max_count = max(counts.values())
        num_rows = 0
        while num_rows < max_count:
            new_row = []
            for k in counts:
                v = counts[k]
                if v > 0:
                    counts[k] -= 1
                    new_row.append(k)
            out.append(new_row)
            num_rows += 1
        return out

