class Solution:
    def minOperations(self, nums: List[int]) -> int:
        counts = {}
        for n in nums:
            if n in counts:
                counts[n] += 1
            else:
                counts[n] = 1
        # all we care about is counts.values()
        def num_ops(n):
            if n < 2:
                return -1 # impossible
            if n % 3 == 0:
                return n // 3
            # if n % 3 == 1: # 4 left over
            return 2 + ((n-4)//3)
        total = 0
        for n in counts.values():
            ops = num_ops(n)
            if ops == -1:
                return -1
            total += ops
        return total

