    def findLeastNumOfUniqueInts(self, arr: List[int], k: int) -> int:
        d = {}
        for i in arr:
            if i in d: d[i] += 1
            else: d[i] = 1
        num_unique = len(d)
        s = sorted(d, key=d.__getitem__)
        used = 0
        idx = 0
        while used < k and idx < len(s):
            if d[s[idx]] + used <= k:
                used += d[s[idx]]
                num_unique -= 1
                idx += 1
            else:
                break
        return num_unique

