class Solution:
    def findCheapestPrice(self, n: int, flights: List[List[int]], src: int, dst: int, k: int) -> int:
        flights_graph = {}
        for s,d,p in flights:
            if s in flights_graph: 
                print('seen', s, 'already - appending', (d,p), 'now')
                flights_graph[s].append((d,p))
            else: flights_graph[s] = [(d,p)]
        # idea - dfs from src to dst with at most k stops 
        # if k reached and dst not reached, then return inf
        # then take min over all possible routes within dfs
        # if final returned value is inf, return -1
        # otherwise return the dfs value
        global seen
        seen = {}
        def dfs(city, steps_remaining):
            global seen
            if (city, steps_remaining) in seen: return seen[(city, steps_remaining)]
            if city == dst: 
                return 0 # found destination
            if steps_remaining == -1:
                return 1e20 # unreachable
            if city not in flights_graph: 
                return 1e30 # no exits
            neighbors = flights_graph[city]
            min_price = 1e40
            for (to,price) in neighbors:
                this_price = price + dfs(to, steps_remaining-1)
                min_price = min(min_price, this_price)
            seen[(city, steps_remaining)] = min_price
            return min_price
        result = dfs(src, k)
        if result > 1e10: return -1
        return result

