class Solution:
    def union(self, parent, size, a, b):
        a_parent = self.find(parent, a)
        b_parent = self.find(parent, b)
        if a_parent == b_parent: return parent, size
        size_a = size[a_parent]
        size_b = size[b_parent]
        if size_a > size_b:
            parent[b_parent] = a_parent
            size[a_parent] += size[b_parent]
        else:
            parent[a_parent] = b_parent
            size[b_parent] += size[a_parent]
        return parent, size

    def find(self, parent, a):
        while a != parent[a]:
            a = parent[a]
        return a

    def connected(self, parent, a, b):
        return self.find(parent, a) == self.find(parent, b)

    def findAllPeople(self, n: int, meetings: List[List[int]], firstPerson: int) -> List[int]:
        global_parent = [i for i in range(n)]
        global_size = [1 for _ in range(n)]
        meetings = [[0, firstPerson, 0]] + meetings
        meeting_groups = {}
        for meeting in meetings:
            p1, p2, time = meeting
            if time in meeting_groups: meeting_groups[time].append((p1,p2))
            else: meeting_groups[time] = [(p1,p2)]

        grouped_meetings = sorted(meeting_groups.items(), key=lambda x:x[0])
        grouped_meetings = [groups for time,groups in grouped_meetings]

        # globally connect all people to 0 if they are locally connected to 0
        for groups in grouped_meetings:
            local_population = {person for person in chain(*groups)} | {0}
            local_parent = {i:i for i in local_population}
            local_size = {i:1 for i in local_population}
            for p1, p2 in groups:
                local_parent, local_size = self.union(local_parent, local_size, p1, p2)
            for p1, p2 in groups:
                if self.connected(global_parent, p1, 0) or self.connected(global_parent, p2, 0):
                    self.union(local_parent, local_size, p1, 0) # wlog choose p1
            for p1, p2 in groups:
                if self.connected(local_parent, p1, 0): # wlog choose p1
                    self.union(global_parent, global_size, p1, 0)
                    self.union(global_parent, global_size, p2, 0)

        secretholders = [i for i in range(n) if self.connected(global_parent, i, 0)]
        return secretholders

