class Solution:
    def union(self, a, b):
        # combine the components of these two nodes
        a_parent = self.find(a)
        b_parent = self.find(b)

        if a_parent == b_parent:
            return

        # put smaller under larger
        if self.size[a_parent] > self.size[b_parent]:
            # a is bigger than b, put b under a
            self.parent[b_parent] = a_parent
            self.size[a_parent] += self.size[b_parent]
        else:
            # b is bigger than a, put a under b
            self.parent[a_parent] = b_parent
            self.size[b_parent] += self.size[a_parent]

    def find(self, a):
        # find parent of this node
        while self.parent[a] != a:
            a = self.parent[a]
        return a

    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        # edge case
        if len(nums) == 1:
            return True

        # remove duplicates
        nums = list(set(nums))
        # edge case
        if len(nums) == 1:
            if nums[0] > 1:
                return True
            return False

        # union find backing arrays
        self.parent = {idx : idx for idx in range(len(nums))}
        self.size = {idx : 1 for idx in range(len(nums))}

        # create a backing array of size 1 + max(nums)
        # first_index_with_prime_factor[p] will hold the first index to have p as a prime factor
        # so when we find another number with p as a prime factor,
        # we will connect it with first_index[p]
        first_index_with_prime_factor = [-1] * (1 + max(nums))

        # connect all numbers that share a prime factor
        for idx,num in enumerate(nums):
            # iterate through possible prime factors of num (besides num)
            for factor_candidate in range(2, num):
                # if out of range for sub-num prime factors, exit
                # and mark num itself as prime if it had no other prime factors
                if factor_candidate * factor_candidate > num:
                    if num > 1: # was not divided by prime factors all the way to 1
                        # thus, num itself is prime
                        # update first_index_with_prime_factor backing array to reflect this
                        if first_index_with_prime_factor[num] == -1:
                            first_index_with_prime_factor[num] = idx
                        else:
                            self.union(first_index_with_prime_factor[num], idx)
                    break # no need to continue enumerating at this point
                # num is not divisible by factor_candidate, so factor_candidate is not a factor
                # skip this factor candidate
                if num % factor_candidate: continue
                # update first_index_with_prime_factor backing array
                if first_index_with_prime_factor[factor_candidate] == -1:
                    first_index_with_prime_factor[factor_candidate] = idx
                else:
                    self.union(first_index_with_prime_factor[factor_candidate], idx)
                # divide num by the factor we've found until there are no instances left
                # note that this step prevents any composite factors from being chosen
                # e.g., 4 will never be chosen as if a number is divisible by 4,
                # all 2's will be divided out at this step and the number will no longer
                # be divisible by 4
                while not (num % factor_candidate): num //= factor_candidate
            # edge case - num itself is 2. obviously 2 is prime, so mark backing array
            # but we never hit 2 as range(2,2) is an empty range
            # as having 2 (or merge if already filled)
            if num == 2:
                if first_index_with_prime_factor[2] == -1:
                    first_index_with_prime_factor[2] = idx
                else:
                    self.union(first_index_with_prime_factor[2], idx)

        # all elements are in a single component
        return self.size[self.find(0)] == len(nums)

