class Solution:
    def isSameTree(self, p: Optional[TreeNode], q: Optional[TreeNode]) -> bool:
        def flattenTree(root):
            if root is None:
                return 'X'
            return '({} l {}, r {})'.format(root.val, flattenTree(root.left), flattenTree(root.right))
        return flattenTree(p) == flattenTree(q)

