use std::cell::RefCell;
impl Solution {
    pub fn is_same_tree(p: Option<Rc<RefCell<TreeNode>>>, q: Option<Rc<RefCell<TreeNode>>>) -> bool {
        fn flatten_tree(root: Option<Rc<RefCell<TreeNode>>>) -> String {
            match root {
                Some(node) => format!(
                    "({} l {}, r {})",
                    node.borrow().val, 
                    flatten_tree(node.borrow().left.clone()),
                    flatten_tree(node.borrow().right.clone())),
                None => String::from("X")
            }
        }
        return flatten_tree(p) == flatten_tree(q);
    }
}

