class Solution:
    def findBottomLeftValue(self, root: Optional[TreeNode]) -> int:
        self.best = (-1, -1, None) # (depth, num_lefts, val)
        def dfs(root, num_lefts, depth):
            if root is None:
                return
            if root.left is None and root.right is None: # leaf
                best_depth, best_lefts, _ = self.best
                if depth > best_depth:
                    self.best = (depth, num_lefts, root.val)
                elif depth == best_depth:
                    if num_lefts > best_lefts:
                        self.best = (depth, num_lefts, root.val)
                return
            if root.right is not None:
                dfs(root.right, num_lefts, depth+1)
            if root.left is not None:
                # value shallower left-choices more than deeper ones
                dfs(root.left, num_lefts+1/(2**depth), depth+1)
            return
        dfs(root, 0, 0)
        print(self.best)
        _, _, val = self.best
        return val

