class Solution:
    def isEvenOddTree(self, root: Optional[TreeNode]) -> bool:
        self.depth_nodes = {}
        def dfs(root, depth):
            if not root: return
            if depth in self.depth_nodes:
                self.depth_nodes[depth].append(root.val)
            else:
                self.depth_nodes[depth] = [root.val]
            dfs(root.left, depth+1)
            dfs(root.right, depth+1)
        dfs(root, 0)
        good = True
        for depth in sorted(self.depth_nodes):
            if depth % 2:
                good = good and not any(node % 2 for node in self.depth_nodes[depth])
                good = good and len(set(self.depth_nodes[depth])) == len(self.depth_nodes[depth])
                good = good and sorted(self.depth_nodes[depth], reverse=True) == self.depth_nodes[depth]
            else:
                good = good and all(node % 2 for node in self.depth_nodes[depth])
                good = good and len(set(self.depth_nodes[depth])) == len(self.depth_nodes[depth])
                good = good and sorted(self.depth_nodes[depth]) == self.depth_nodes[depth]
            if not good:
                return False
        return good

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:
        self.solutions = []
        self.n = n
        def validParentheses(s):
            t = 0
            for c in s:
                if c == ')':
                    t -= 1
                    if t < 0:
                        return False
                if c == '(':
                    t += 1
            return t == 0
        def dfs(s, numParensRemaining):
            if numParensRemaining == 0:
                if validParentheses(s):
                    self.solutions.append(s)
            else:
                if s.count('(') > s.count(')'):
                    dfs(s + ')', numParensRemaining-1)
                if s.count('(') < self.n:
                    dfs(s + '(', numParensRemaining-1)
        dfs('', n*2)
        return self.solutions

