class Solution:
    def spiralOrder(self, matrix: List[List[int]]) -> List[int]:
        self.bounds = {
            'left' : -1,
            'up' : 0,
            'right' : len(matrix[0]),
            'down' : len(matrix)
        }
        self.direction = 'right'
        def next_rc(r, c,):
            # if next is OOB, set new direction and return None
            if self.direction == 'right':
                if c+1 == self.bounds['right']:
                    self.direction = 'down'
                    self.bounds['right'] -= 1
                    return None
                return r, c+1
            if self.direction == 'left':
                if c-1 == self.bounds['left']:
                    self.direction = 'up'
                    self.bounds['left'] += 1
                    return None
                return r, c-1
            if self.direction == 'up':
                if r-1 == self.bounds['up']:
                    self.direction = 'right'
                    self.bounds['up'] += 1
                    return None
                return r-1, c
            if self.direction == 'down':
                if r+1 == self.bounds['down']:
                    self.direction = 'left'
                    self.bounds['down'] -= 1
                    return None
                return r+1, c
        out = []
        r, c = 0, 0
        while len(out) < len(matrix[0]) * len(matrix):
            out.append(matrix[r][c])
            next_result = next_rc(r, c)
            if next_result is None:
                next_result = next_rc(r, c)
                if next_result is None:
                    break
            r, c = next_result
        return out

