class NFA:
    def __init__(self, pattern, alphabet):
        '''
        NFA representing the given (regex-subset) pattern.
        '$' refers to the empty string.
        '''
        self.alphabet = alphabet | {'$'}
        self.pattern = pattern
        self.init_state = -1
        self.transitions = {}
        prev_state, current_state, next_state = None, self.init_state, self.init_state+1
        for c in pattern:
            if c == '*':
                # wildcards make self-transitions (loops) on full alphabet
                # and then a transition to the next state on full alphabet
                self.transitions[current_state] = {letter:{current_state, next_state} 
                                                   for letter in self.alphabet}
                # also make a transition on empty string (parsed specially during match)
                self.transitions[current_state]['$'] = {next_state}
            elif c == '?':
                # question marks make a transition to next state on full alphabet
                self.transitions[current_state] = {letter:{next_state} for letter in self.alphabet - {'$'}}
            else:
                # characters make a transition to next state on character
                self.transitions[current_state] = {c:{next_state}}
            current_state, next_state = next_state, next_state+1
        self.states = [self.init_state] + list(range(next_state))
        self.final_state = self.states[-1]
        # add self-transitions on '$' to make logic work
        for state in self.states:
            if state not in self.transitions:
                self.transitions[state] = {'$':{state}}
                continue
            if '$' in self.transitions[state]:
                self.transitions[state]['$'].add(state)
            else:
                self.transitions[state]['$'] = {state}

    def empty_transition(self, stateset):
        out = set()
        for state in stateset:
            out |= self.transitions[state]['$']
        return out | stateset

    def epsilon_closure(self, stateset):
        prev = sorted(stateset)
        stateset = self.empty_transition(stateset)
        while stateset != prev:
            prev = stateset
            stateset = self.empty_transition(stateset)
        return stateset

    def apply_transitions(self, stateset, c):
        out = set()
        for state in stateset:
            if state in self.transitions:
                if c in self.transitions[state]:
                    out |= self.epsilon_closure(self.transitions[state][c])
        return out

    def match(self, s):
        stateset = {self.init_state}
        for c in '$%s$' % '$'.join(s):
            # print(f'{c=}, {stateset=}')
            stateset = self.apply_transitions(stateset, c)
            # print(f'new {stateset=}')
            if not stateset: return False
        return self.final_state in stateset

    def __str__(self):
        alphabet = 'alphabet: {%s}' % ' '.join(self.alphabet)
        pattern = 'pattern: ' + self.pattern
        states = 'states: {%s}' % ' '.join(map(str, self.states))
        init_state = 'init state: ' + str(self.init_state)
        final_state = 'final state: ' + str(self.final_state)
        transitions = 'transitions:\n'
        for (state, state_transitions) in self.transitions.items():
            transitions += '\t%s ->\n' % state
            for (letter, next_state) in state_transitions.items():
                transitions += '\t\t%s => %s\n' % (letter, next_state)
        return '\n'.join([alphabet, pattern, states, init_state, final_state, transitions])

