class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        def valid(address):
            return all(len(x) == len(str(int(x))) and 0 <= int(x) <= 255 for x in address.split('.'))
        out = []
        # choose 3 places to put dots out of the possibilities
        address_dots = combinations(range(1, len(s)), 3)
        for address_dot in address_dots:
            address = '.'.join((
                s[:address_dot[0]],
                s[address_dot[0]:address_dot[1]],
