class Solution:
    def bagOfTokensScore(self, tokens: List[int], power: int) -> int:
        if len(tokens) == 0: return 0
        if len(tokens) == 1: return int(tokens[0] <= power)
        tokens.sort()
        score = 0
        left, right = 0, len(tokens)-1
        '''
        left + 1 - gain score, lose power
        right - 1 - lose score, gain power
        '''
        while left <= right:
            # print('left', left, 'right', right, 'tokens[left]', tokens[left], 'tokens[right]', tokens[right])
            if left == right:
                if tokens[left] > power:
                    break
            if power >= tokens[left]:
                power -= tokens[left]
                score += 1
                left += 1
                # print('chose left, power', power, 'score', score)
            elif score > 0 and power + tokens[right] >= tokens[left]:
                power += tokens[right]
                score -= 1
                right -= 1
                # print('chose right, power', power, 'score', score)
            else:
                # print('done')
                break
        return score

class Solution:
    def minimumLength(self, s: str) -> int:
        if len(s) < 2: return len(s)
        counts = []
        current = s[0]
        current_count = 1
        for c in s[1:]:
            if c == current:
                current_count += 1
            else:
                counts.append((current, current_count))
                current_count = 1
                current = c
        counts.append((current, current_count))
        total_len = len(s)
        while len(counts) > 1 and counts[0][0] == counts[-1][0]:
            _,startcount = counts.pop(0)
            _,endcount = counts.pop()
            total_len -= (startcount + endcount)

        if len(counts) == 1:
            if counts[0][1] == 1:
                return 1
            return 0

        return total_len

