        have = {5 : 0, 10 : 0}
        for bill in bills:
            if bill == 5:
                have[5] += 1
            if bill == 10:
                if have[5] < 1:
                    return False
                have[5] -= 1
                have[10] += 1
            if bill == 20:
                if have[5] < 1:
                    return False
                if have[10] < 1:
                    if have[5] < 3:
                        return False
                    have[5] -= 3
                else:
                    have[10] -= 1
                    have[5] -= 1
        return True

