class Solution:
    def findMinArrowShots(self, points: List[List[int]]) -> int:
        points.sort(key=lambda x:x[0])
        # idea - shrink interval as we go until non-overlapping found
        arrows_needed = 1
        current_interval = None
        for point in points:
            if current_interval is None:
                current_interval = point
                continue
            c1, c2 = current_interval
            p1, p2 = point
            if p1 > c2:
                # this interval no longer overlaps with current streak
                arrows_needed += 1
                current_interval = point
            else:
                current_interval = [max(c1, p1), min(c2, p2)]
        return arrows_needed

