class Solution:
    def hasPathSum(self, root: Optional[TreeNode], targetSum: int) -> bool:
        if root is None: return False
        def helper(root, sum_so_far):
            if root.left is None and root.right is None:
                return root.val + sum_so_far == targetSum
            if root.left is None: return helper(root.right, sum_so_far + root.val)
            if root.right is None: return helper(root.left, sum_so_far + root.val)
            return helper(root.left, sum_so_far + root.val) or helper(root.right, sum_so_far + root.val)
        return helper(root, 0)

