class Solution:
    def isBalanced(self, root: Optional[TreeNode]) -> bool:
        def helper(root):
            if root is None: return (True, 0)
            l_good, l_height = helper(root.left)
            r_good, r_height = helper(root.right)
            if not (l_good and r_good): return (False, -1)
            if abs(l_height - r_height) > 1: return (False, -1)
            return (True, max(l_height, r_height) + 1)
        good, _ = helper(root)
        return good

class Solution:
    def subarraysWithKDistinct(self, nums: List[int], k: int) -> int:
        # idea: get count of subarrays with <= k distinct elements
        # and subtract count of subarrays with <= k-1 distinct elements
        # to get count of subarrays with exactly k distinct elements
        def helper(nums, m):
            # number of subarrays with <= m distinct elements
            # sliding window
            l = r = num_subarrays = 0
            window_counts = Counter()
            while r < len(nums):
                window_counts[nums[r]] += 1
                while len(window_counts) > m and l <= r:
                    # if removing last one, delete from dict
                    if window_counts[nums[l]] == 1:
                        del window_counts[nums[l]]
                    else:
                        window_counts[nums[l]] -= 1
                    l += 1
                num_subarrays += r - l + 1
                r += 1
            return num_subarrays
        return helper(nums, k) - helper(nums, k-1)

class Solution:
    def countSubarrays(self, nums: List[int], minK: int, maxK: int) -> int:
        blocks = []
        prev_index = 0
        # divide nums into blocks where all numbers are in [min..max]
        for i,e in enumerate(nums):
            if e < minK or e > maxK:
                block = nums[prev_index:i]
                if len(block) > 0:
                    blocks.append(block)
                prev_index = i+1
        last_block = nums[prev_index:]
        if len(last_block) > 0:
            blocks.append(last_block)
        # remove blocks missing minK and maxK
        blocks = [b for b in blocks if min(b) == minK and max(b) == maxK]
        # print(blocks)
        def block_count(block):
            # sliding window - check for presence of both min and max elements
            # num with min and max is total minus without min or max
            n = len(block)
            total_subarrays = (n*(n+1))//2
            l = r = num_subarrays = 0
            mincount = maxcount = 0
            while r < len(block):
                if block[r] == minK:
                    mincount += 1
                if block[r] == maxK:
                    maxcount += 1
                # only include subarrays without both min and max
                while (mincount > 0 and maxcount > 0) and l <= r:
                    # print(mincount, maxcount, l, r, block)
                    if block[l] == minK:
                        mincount -= 1
                    if block[l] == maxK:
                        maxcount -= 1
                    l += 1
                num_subarrays += r - l + 1
                r += 1
            return total_subarrays - num_subarrays
        return sum(block_count(block) for block in blocks)

class Solution:
    def exist(self, board: List[List[str]], word: str) -> bool:
        # edge case to save time - count letter frequencies
        all_letters = []
        for row in board:
            all_letters += row
        c = Counter(all_letters)
        c_word = Counter(word)
        if not all(c[letter] >= c_word[letter] for letter in word):
            return False

        def neighbors(r, c):
            out = []
            if r > 0: out.append((r-1, c))
            if r < len(board)-1: out.append((r+1, c))
            if c > 0: out.append((r, c-1))
            if c < len(board[0])-1: out.append((r, c+1))
            return out

        def tileHasSolution(r, c):
            # check first character
            if board[r][c] != word[0]:
                return False
            if len(word) == 1:
                return True
            # dfs
            seen = {(r, c)}
            def helper(rh, ch, seenh, wordh):
                # print(f'helper: {rh=}, {ch=}, {seenh=}, {wordh=}')
                if (rh, ch) in seenh:
                    return False
                if board[rh][ch] != wordh[0]:
                    return False
                if len(wordh) == 1: 
                    return True
                seenh_next = seenh | {(rh, ch)}
                return any(helper(*neighbor, seenh_next, wordh[1:])
                           for neighbor in neighbors(rh, ch))
            return any(helper(*neighbor, seen, word[1:])
                       for neighbor in neighbors(r, c))

        return any(tileHasSolution(r, c) for (r, c) in product(range(len(board)), range(len(board[0]))))

