class Solution:
    def isInterleave(self, s1: str, s2: str, s3: str) -> bool:
        if len(s1 + s2) != len(s3): return False
        if s1 + s2 == s3 or s2 + s1 == s3: return True
        dp = { (len(s1), len(s2)) : True } # { i,j : interleave possible }
        def dfs(i, j):
            # at index i in s1 and index j in s2
            if (i,j) in dp:
                return dp[i,j]
            # therefore at index k in s3
            k = i + j
            if i < len(s1) and s1[i] == s3[k] and (j >= len(s2) or s2[j] != s3[k]):
                # must progress on s1
                out = dfs(i+1, j)
                dp[i,j] = out
                return out
            if j < len(s2) and s2[j] == s3[k] and (i >= len(s1) or s1[i] != s3[k]):
                # must progress on s2
                out = dfs(i, j+1)
                dp[i,j] = out
                return out
            if (i < len(s1) and s1[i] == s3[k]) and (j < len(s2) and s2[j] == s3[k]):
                # could progress on either
                out = dfs(i+1, j) or dfs(i, j+1)
                dp[i,j] = out
                return out
            return False

        return dfs(0, 0)

class Solution:
    def minimumTotal(self, triangle: List[List[int]]) -> int:
        dp = {} # { (r,c) : min path sum }
        def choices(r, c):
            # two choices - left or right
            return ((r+1, c), (r+1, c+1))
        def dfs(r, c):
            if (r, c) in dp:
                return dp[r,c]
            if r == len(triangle)-1:
                return triangle[r][c]
            out = triangle[r][c] + min(dfs(*choice) for choice in choices(r, c))
            dp[r,c] = out
            return out
        return dfs(0, 0)

