class Solution:
    def minTimeToVisitAllPoints(self, points: List[List[int]]) -> int:
        def travelTime(p1, p2):
            # while y dist and x dist are both nonzero,
            # move diagonally towards y and x simultaneously
            # then, move remaining distance in single direction
            # this is equivalent to max(x_dist, y_dist)
            x1, y1 = p1
            x2, y2 = p2
            x_dist = abs(x1-x2)
            y_dist = abs(y1-y2)
            return max(x_dist, y_dist)
        return sum(travelTime(a, b) for a, b in pairwise(points))

