class Solution:
    def maximalRectangle(self, matrix: List[List[str]]) -> int:
        matrix = [[int(x) for x in row] for row in matrix]
        def combine_rows(r1, r2):
            out = []
            for i,j in zip(r1, r2):
                if j == 0:
                    out.append(0)
                else:
                    out.append(i+j)
            return out
        def largest_rect(row):
            stack = []
            best = 0
            for i in range(len(row)):
                while stack and row[i] < row[stack[-1]]:
                    height = row[stack.pop()]
                    left = -1 if not stack else stack[-1]
                    width = i - left - 1
                    best = max(best, height * width)
                stack.append(i)
            while stack:
                height = row[stack.pop()]
                left = -1 if not stack else stack[-1]
                width = len(row) - left - 1
                best = max(best, height * width)
            return best
        combined = matrix[0]
        best = largest_rect(combined)
        for row in matrix[1:]:
            combined = combine_rows(combined, row)
            best = max(best, largest_rect(combined))
        return best

