        self.strings = []
        def dfs(root, string):
            string += str(root.val)
            if not root.left and not root.right:
                self.strings.append(string)
                return
            if root.left:
                dfs(root.left, string)
            if root.right:
                dfs(root.right, string)
        dfs(root, '')
        return sum(int(s) for s in self.strings)

