class Solution:
    def addOneRow(self, root: Optional[TreeNode], val: int, depth: int) -> Optional[TreeNode]:
        if depth == 1:
            new_root = TreeNode(val=val, left=root)
            return new_root
        def helper(root, current_depth):
            if current_depth == depth-1:
                if root.left:
                    root.left = TreeNode(val=val, left=root.left)
                else:
                    root.left = TreeNode(val=val)
                if root.right:
                    root.right = TreeNode(val=val, right=root.right)
                else:
                    root.right = TreeNode(val=val)
            else:
                if root.left:
                    helper(root.left, current_depth+1)
                if root.right:
                    helper(root.right, current_depth+1)
        helper(root, 1)
        return root

