            this_char = chr(root.val+ord('a'))
            if root.left is None and root.right is None:
                self.strings.add((string_so_far + this_char)[::-1])
            else:
                if root.left:
                    helper(root.left, string_so_far + this_char)
                if root.right:
                    helper(root.right, string_so_far + this_char)
        helper(root, '')
        best = sorted(self.strings)[0]
