class Solution:
    def numIslands(self, grid: List[List[str]]) -> int:
        # idea - iterate through until find a 1
        # then, increment a counter and dfs on the 1
        # during dfs, mark all 1s as 0
        # then continue iterating etc until the end
        def neighbors(r, c):
            left = (r, c-1)
            right = (r, c+1)
            up = (r-1, c)
            down = (r+1, c)
            out = []
            if r > 0: out.append(up)
            if r < len(grid)-1: out.append(down)
            if c > 0: out.append(left)
            if c < len(grid[0])-1: out.append(right)
            return out

        def dfs(r, c):
            if grid[r][c] == '1':
                grid[r][c] = '0'
                for neighbor in neighbors(r,c):
                    dfs(*neighbor)

        total_islands = 0
        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == '1':
                    total_islands += 1
                    dfs(r, c)
        return total_islands

class Solution:
    def findFarmland(self, land: List[List[int]]) -> List[List[int]]:
        # idea - iterate through until find a 1
        # then, go right until 0 (or end) seen to get right side
        # and go down until 0 (or end) seen to get bottom side
        # add [top, left, bottom, right] to output list
        # mark all in range top <= row <= bottom and left <= col <= right as 0
        # then continue iterating etc until the end
        def rightmost_column(r, c):
            while c < len(land[0]):
                if land[r][c] == 0:
                    break
                c += 1
            return c-1

        def bottommost_row(r,c):
            while r < len(land):
                if land[r][c] == 0:
                    break
                r += 1
            return r-1

        def mark_as_0(r1, c1, r2, c2):
            for r in range(r1, r2+1):
                for c in range(c1, c2+1):
                    land[r][c] = 0

        out = []
        for r1 in range(len(land)):
            for c1 in range(len(land[0])):
                if land[r1][c1] == 1:
                    r2 = bottommost_row(r1, c1)
                    c2 = rightmost_column(r1, c1)
                    out.append([r1, c1, r2, c2])
                    mark_as_0(r1, c1, r2, c2)

        return out

class Solution:
    def union(self, a, b):
        # combine the components of these two nodes
        a_parent = self.find(a)
        b_parent = self.find(b)

        if a_parent == b_parent:
            return

        # put smaller under larger
        if self.size[a_parent] > self.size[b_parent]:
            # a is bigger than b, put b under a
            self.parent[b_parent] = a_parent
            self.size[a_parent] += self.size[b_parent]
        else:
            # b is bigger than a, put a under b
            self.parent[a_parent] = b_parent
            self.size[b_parent] += self.size[a_parent]

    def find(self, a):
        # find parent of this node
        while self.parent[a] != a:
            a = self.parent[a]
        return a

    def connected(self, a, b):
        return self.find(a) == self.find(b)

    def validPath(self, n: int, edges: List[List[int]], source: int, destination: int) -> bool:
        self.parent = [i for i in range(n)]
        self.size = [1 for i in range(n)]
        for i,j in edges:
            self.union(i,j)
        return self.connected(source, destination)

class Solution:
    def openLock(self, deadends: List[str], target: str) -> int:
        deadends = set(deadends)
        if '0000' in deadends:
            return -1
        if '0000' == target:
            return 0

        digits = set(str(i) for i in range(10))

        def digit_neighbors(d):
            if d == '0': return ['9', '1']
            if d == '9': return ['8', '0']
            i = int(d)
            return str(i-1), str(i+1)

        visited_set = {'0000'}

        def get_neighbors(s):
            out = set()
            for i,d in enumerate(s):
                for neighbor in digit_neighbors(d):
                    out.add(s[:i] + neighbor + s[i+1:])
            return out - deadends

        def bfs():
            q = collections.deque()
            q.append('0000')
            prev = [-1] * 10_000
            while q:
                # print('q', q)
                node = q.popleft()
                neighbors = get_neighbors(node)
                for neighbor in neighbors - visited_set:
                    visited_set.add(neighbor)
                    index = int(neighbor)
                    q.append(neighbor)
                    prev[index] = node
                    if node == target:
                        return prev
            return prev

        def reconstruct_path(prev):
            path = []
            location = target
            while location != '0000':
                location = prev[int(location)]
                path.append(location)
            return path[::-1]
        prev = bfs()
        if prev[int(target)] == -1:
            return -1
        path = reconstruct_path(prev)
        # print(path)
        return len(path)

class Solution:
    def tribonacci(self, n: int) -> int:
        self.memo = {0 : 0, 1 : 1, 2 : 1}
        def helper(n):
            if n in self.memo:
                return self.memo[n]
            out = helper(n-1) + helper(n-2) + helper(n-3)
            self.memo[n] = out
            return out
        return helper(n)

