class Solution:
    def longestIdealString(self, s: str, k: int) -> int:
        # at each step, best[c] is the best string ending in c
        # that we looked at previously
        # so, we want to choose the best length we saw previously
        # as long as it is within range, which means
        # 0 < next char < 26 and the diff is within range of k
        best = [0] * 26
        for c in s:
            c = ord(c) - ord('a')
            best[c] = max(best[max(0, c-k):min(26, c+k+1)]) + 1
        return max(best)

class Solution:
    def helper(self, i,j):
        if (i,j) in self.minsum:
            return self.minsum[i,j]
        if i + 1 == self.n:
            self.minsum[i,j] = self.matrix[i][j]
            return self.matrix[i][j]
        options = (self.helper(i+1, _j) for _j in range(self.n) if _j != j)
        minsum = min(options) + self.matrix[i][j]
        self.minsum[i,j] = minsum
        return minsum
