        self.minsum = {} # (i,j) => min sum from matrix[i][j]
        self.matrix = grid
        self.n = len(grid)

        for row in range(self.n):
            for col in range(self.n):
                self.helper(row, col)

        minval = 1e100
        for (r,c),v in self.minsum.items():
            if r == 0:
                if v < minval:
                    minval = v

        return minval

class Solution:
    def findRotateSteps(self, ring: str, key: str) -> int:
        # dp[i][j] is the lowest number of steps remaining
        # at position i after j characters of key
        dp = {}

        def get_left_index(i, c):
            idx = ring.rfind(c, 0, i)
            if idx == -1:
                idx = ring.rfind(c)
                dist = i + len(ring) - idx
                return idx, dist
            else:
                dist = i - idx
                return idx, dist

        def get_right_index(i, c):
            idx = ring.find(c, i)
            if idx == -1:
                idx = ring.find(c)
                dist = len(ring) - i + idx
                return idx, dist
            else:
                dist = idx - i
                return idx, dist

        def helper(i, j):
            if (i,j) in dp:
                return dp[i,j]
            if j == len(key):
                return 0
            c = key[j]
            if c == ring[i]:
                # don't need to move
                out = 1 + helper(i, j+1)
            else:
                left_idx, left_dist = get_left_index(i, c)
                left_steps = 1 + left_dist + helper(left_idx, j+1)
                right_idx, right_dist = get_right_index(i, c)
                right_steps = 1 + right_dist + helper(right_idx, j+1)
                out = min(left_steps, right_steps)
            dp[i,j] = out
            return out

        result = helper(0, 0)
        return result

