class Solution:
    def sumOfDistancesInTree(self, n: int, edges: List[List[int]]) -> List[int]:
        if not edges: return [0]

        # start by looking from perspective of node 0
        # count[i] = # of nodes in subtree i
        count = [1] * n
        # distsum[i] = sum of dists in subtree i
        distsum = [0] * n

        # convert to adjacency dictionary
        adj = [0] * n
        for i,j in edges:
            if not adj[i]: adj[i] = {j}
            else: adj[i].add(j)
            if not adj[j]: adj[j] = {i}
            else: adj[j].add(i)

        # can do an optimization because of tree structure
        # only need to pass parent, no need to
        # keep track of visited at all
        def postorder(root, parent):
            for child in adj[root]:
                if child == parent: continue
                postorder(child, root)
                count[root] += count[child]
                distsum[root] += distsum[child] + count[child]

        def preorder(root, parent):
            for child in adj[root]:
                if child == parent: continue
                distsum[child] = distsum[root] - 2*count[child] + n
                preorder(child, root)

        postorder(0, -1)
        preorder(0, -1)

        return distsum

