class Solution:
    def compareVersion(self, version1: str, version2: str) -> int:
        v1 = [int(x) for x in version1.split('.')]
        v2 = [int(y) for y in version2.split('.')]
        maxlen = max(len(v1), len(v2))
        v1 += [0] * (maxlen - len(v1))
        v2 += [0] * (maxlen - len(v2))
        p1, p2 = 0, 0
        while p1 < len(v1):
            if v1[p1] > v2[p2]:
                return 1
            elif v1[p1] < v2[p2]:
                return -1
            p1 += 1
            p2 += 1
        return 0

class Solution:
    def numRescueBoats(self, people: List[int], limit: int) -> int:
        people.sort()
        people = [p for p in people if p <= limit]
        people = deque(people)
        total_boats = 0
        while people:
            if len(people) == 1:
                return total_boats + 1
            if people[0] + people[-1] > limit:
                people.pop()
                total_boats += 1
            else:
                people.popleft()
                people.pop()
                total_boats += 1
        return total_boats

