class Solution:
    def levelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        self.levels = []
        def dfs(root, depth):
            if root is None:
                return
            if len(self.levels) - 1 < depth:
                self.levels.append([root.val])
            else:
                self.levels[depth].append(root.val)
            dfs(root.left, depth+1)
            dfs(root.right, depth+1)
        dfs(root, 0)
        return self.levels

