class Solution:
    def sortedArrayToBST(self, nums: List[int]) -> Optional[TreeNode]:
        def helper(L):
            if len(L) == 0:
                return None
            if len(L) == 1:
                return TreeNode(val=L[0])
            if len(L) == 2:
                return TreeNode(val=L[0], right=TreeNode(val=L[1]))
            mid = len(L)//2
            left = helper(L[:mid])
            right = helper(L[mid+1:])
            return TreeNode(val=L[mid], left=left, right=right)
        return helper(nums)

