class Solution:
    def findTheLongestBalancedSubstring(self, s: str) -> int:
        if len(s) <= 1: return 0
        i = 0
        while s[i] != '0':
            i += 1
            if i >= len(s) - 1: return 0
        zero = True
        zero_len = 1
        one_len = 0
        best = 0
        i += 1
        while i < len(s):
            if zero:
                if s[i] == '0':
                    zero_len += 1
                else:
                    zero = False
                    one_len = 1
                    best = max(best, 2 * min(zero_len, one_len))
            else:
                if s[i] == '0':
                    zero = True
                    zero_len = 1
                    one_len = 0
                else:
                    one_len += 1
                    best = max(best, 2 * min(zero_len, one_len))
            i += 1
        return best

use std::collections::HashSet;
impl Solution {
    pub fn diagonal_prime(nums: Vec<Vec<i32>>) -> i32 {
        let mut primes: HashSet<i32> = HashSet::from([2, 3, 5, 7, 11, 13]);
        let mut nonprimes: HashSet<i32> = HashSet::from([0, 1]);
        fn is_prime(n: i32, primeset: &mut HashSet<i32>, nonprimeset: &mut HashSet<i32>) -> bool {
            if primeset.contains(&n) {
                return true;
            } else if nonprimeset.contains(&n) {
                return false;
            } else {
                let mut best = 0;
                let upper_bound = (n as f64).sqrt() as i32 + 1;
                for i in (2..upper_bound) {
                    if n % i == 0 {
                        nonprimeset.insert(n);
                        return false;
                    }
                }
                primeset.insert(n);
                return true;
            }
        }
        let mut best: i32 = 0;
        for i in (0..nums.len()) {
            let a = nums[i][i];
            let b = nums[i][nums.len()-i-1];
            if a > best && is_prime(a, &mut primes, &mut nonprimes) {
                best = a;
            }
            if b > best && is_prime(b, &mut primes, &mut nonprimes) {
                best = b;
            }
        }
        return best;
    }
}

class Solution:
    def isPrime(self, n):
        if n in self.prime: return True
        if n in self.not_prime: return False
        for i in range(2,int(n**0.5)+1):
            if not n % i:
                self.not_prime.add(n)
                return False
        self.prime.add(n)
        return True

    def diagonalPrime(self, nums: List[List[int]]) -> int:
        self.prime = {2,3,5,7,11,13}
        self.not_prime = {0,1}
        best = 0
        for i in range(len(nums)):
            a, b = nums[i][i], nums[i][len(nums)-i-1]
            if a > best and self.isPrime(a):
                best = a
            if b > best and self.isPrime(b):
                best = b
        return best

class Solution:
