impl Solution {
    pub fn kth_smallest_prime_fraction(arr: Vec<i32>, k: i32) -> Vec<i32> {
        let mut heap = BinaryHeap::new();
        let n = 0;
        for d in 0..arr.len() {
            heap.push((MyFloat((-arr[n] as f64)/(arr[d] as f64)), n, d));
        }

        let mut total_popped = 0;
        while total_popped < k-1 {
            let (_, n, d) = heap.pop().unwrap();
            if n+1 < arr.len() {
                heap.push((MyFloat((-arr[n+1] as f64)/(arr[d] as f64)), n+1, d));
            }
            total_popped += 1;
        }

        let (_, n, d) = heap.pop().unwrap();
        return vec![arr[n], arr[d]];
    }
}

