        wage_to_quality_ratio.sort()
        heap = []
        for ratio, q in wage_to_quality_ratio:
            if len(heap) < k:
                heapq.heappush(heap, -q)
                total_quantity += q
            elif len(heap) == k:
                removed = heapq.heappushpop(heap, -q)
