class Solution:
    def matrixScore(self, grid: List[List[int]]) -> int:
        # first, get ones in all leftmost columns by flipping rows
        # then, for each column after the leftmost, flip if >50% 0s
        for i,row in enumerate(grid):
            if row[0] == 0:
                # print('flipped row', i)
                grid[i] = [1 - grid[i][j] for j in range(len(row))]
        # print('\n'.join(str(row) for row in grid))
        for j, col in enumerate(zip(*grid)):
            if j == 0: continue
            if sum(col) < len(col)/2:
                # print('flipped col', j)
                for i in range(len(grid)):
                    grid[i][j] = 1 - grid[i][j]
        return sum(int(''.join(str(d) for d in row),2) for row in grid)

