// #[derive(Debug, PartialEq, Eq)]
// pub struct TreeNode {
//   pub val: i32,
//   pub left: Option<Rc<RefCell<TreeNode>>>,
//   pub right: Option<Rc<RefCell<TreeNode>>>,
// }
// 
// impl TreeNode {
//   #[inline]
//   pub fn new(val: i32) -> Self {
//     TreeNode {
//       val,
//       left: None,
//       right: None
//     }
//   }
// }
use std::rc::Rc;
use std::cell::RefCell;
impl Solution {
    pub fn find_tilt(root: Option<Rc<RefCell<TreeNode>>>) -> i32 {
        let mut total = Rc::new(RefCell::new(0));
        fn sum_tree(root: Option<Rc<RefCell<TreeNode>>>, total: &Rc<RefCell<i32>>) -> i32 {
            match root {
                Some(node) => {
                    let val = node.borrow().val;
                    let left = sum_tree(node.borrow().left.clone(), total);
                    let right = sum_tree(node.borrow().right.clone(), total);
                    *total.borrow_mut() += (left - right).abs();
                    return val + left + right;
                },
                None => 0
            }
        }
        sum_tree(root, &total);
        return *total.borrow();
    }
}

impl Solution {
    pub fn matrix_reshape(mat: Vec<Vec<i32>>, r: i32, c: i32) -> Vec<Vec<i32>> {
        let n = mat.len();
        let m = mat[0].len();
        let total_size = (n * m) as i32;
        if total_size != r * c {
            return mat;
        }
        let mut out = Vec::new();
        let mut counter = 0;
        let mut row = Vec::new();
        for i in 0..n {
            for j in 0..m {
                row.push(mat[i][j]);
                counter += 1;
                if counter == c {
                    out.push(row.clone());
                    row.clear();
                    counter = 0;
                }
            }
        }
        return out;
    }
}

use std::collections::HashMap;
impl Solution {
    pub fn find_lhs(nums: Vec<i32>) -> i32 {
        // find max count element
        let mut counts: HashMap<i32, i32> = HashMap::new();
        let mut unique_elements: Vec<i32> = Vec::new();
        let n = nums.len();
        for i in 0..n {
            if counts.contains_key(&nums[i]) {
                counts.insert(nums[i], counts[&nums[i]] + 1);
            } else {
                unique_elements.push(nums[i]);
                counts.insert(nums[i], 1);
            }
        }
        // if max count element = len of total arr, return 0
        if counts.len() <= 1 {
            return 0;
        }
        // else, iterate through sorted pairs of keys
        // e.g. 1,2; 2,3; 3,4... 
        // and take best combination sum of counts
        unique_elements.sort();
        let mut best = 0;
        for i in 0..unique_elements.len()-1 {
            let a = unique_elements[i];
            let b = unique_elements[i+1];
            if b - a == 1 {
                best = best.max(counts[&b] + counts[&a]);
            }
        }
        return best;
    }
}

