use std::rc::Rc;
use std::cell::RefCell;
impl Solution {
    pub fn is_subtree(root: Option<Rc<RefCell<TreeNode>>>, sub_root: Option<Rc<RefCell<TreeNode>>>) -> bool {
        // idea - create flattened string representation of root and of subroot trees
        // and then check whether subroot tree string rep is inside the root tree string
        fn flatten_tree(root: Option<Rc<RefCell<TreeNode>>>) -> String {
            match root {
                Some(node) => format!(
                    "({} l {}, r {})",
                    node.borrow().val, 
                    flatten_tree(node.borrow().left.clone()),
                    flatten_tree(node.borrow().right.clone())),
                None => String::from("X")
            }
        }
        return flatten_tree(root).contains(&flatten_tree(sub_root));
    }
}

