class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        loc1 = {}
        for i,e in enumerate(list1):
            loc1[e] = i
        loc2 = {}
        for i,e in enumerate(list2):
            loc2[e] = i
        min_size = float('inf')
        for k in set(loc1) & set(loc2):
            min_size = min(min_size, loc1[k] + loc2[k])
