use std::collections::HashMap;
use std::collections::HashSet;
impl Solution {
    pub fn find_restaurant(list1: Vec<String>, list2: Vec<String>) -> Vec<String> {
        let mut loc1: HashMap<String, usize> = HashMap::new();
        for (i,e) in list1.iter().enumerate() {
            loc1.insert(e.to_string(), i);
        }
        let mut loc2: HashMap<String, usize> = HashMap::new();
        for (i,e) in list2.iter().enumerate() {
            loc2.insert(e.to_string(), i);
        }
        let mut min_size: usize = usize::max_value();
        let key_set: HashSet<String> = {
            let set1: HashSet<String> = loc1.keys().cloned().collect();
            let set2: HashSet<String> = loc2.keys().cloned().collect();
            set1.intersection(&set2).cloned().collect()
        };
        for k in key_set.iter().cloned() {
            min_size = min_size.min(loc1[&k] + loc2[&k]);
        }
        let mut out: Vec<String> = Vec::new();
        for k in key_set.iter().cloned() {
            if loc1[&k] + loc2[&k] == min_size {
                out.push(k);
            }
        }
        return out;
    }
}

