            if j > 0: out.append((i, j-1))
            if i < len(grid)-1: out.append((i+1, j))
            if j < len(grid[0])-1: out.append((i, j+1))
            return out
        def dfs(i,j):
            if grid[i][j] == 0:
                return 0
            init = grid[i][j]
            grid[i][j] = 0
            best = init
            for ni, nj in neighbors(i,j):
                best = max(
                    best,
                    init + dfs(ni, nj)
                )
            grid[i][j] = init
            return best
        best = 0
        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] > 0:
                    curr = dfs(i,j)
                    # print('i,j = {},{}: [{}] => {}'.format(i,j,grid[i][j],curr))
                    if curr > best:
                        best = curr
                        # print('new best found at {},{}: {}'.format(i, j, best))
        return best

class Solution:
    def maximumSafenessFactor(self, grid: List[List[int]]) -> int:
        # idea - multi-source bfs
        # and then binary search by min dist per cell using bfs

        n = len(grid)

        # get all sources
        queue = collections.deque()
        for r in range(n):
            for c in range(n):
                if grid[r][c]:
                    queue.append((r, c, 0))
        # bfs from all sources at once
        def neighbors(r, c):
            out = []
            if r > 0: out.append((r-1, c))
            if c > 0: out.append((r, c-1))
            if r < n-1: out.append((r+1, c))
            if c < n-1: out.append((r, c+1))
            return out

        dist = [[-1 for c in range(n)] 
                    for r in range(n)]
        while queue:
            r,c,d = queue.popleft()
            # already visited
            if dist[r][c] >= 0:
                continue
            # mark as visited
            dist[r][c] = d
            # add neighbors to queue
            for (_r, _c) in neighbors(r, c):
                queue.append((_r, _c, d+1))

        # print('cell distances:')
        # print('\n'.join(str(row) for row in dist))

        # binary search by min dist traversible by bfs from source to dest
        def min_dist_bfs(min_dist):
            memo = [[0 for _ in range(n)]
                       for _ in range(n)]
            queue = collections.deque([(0,0)])
            while queue:
                r,c = queue.popleft()
                # already visited
                if memo[r][c]:
                    continue
                # square not usable
                if dist[r][c] < min_dist:
                    continue
                # mark as visited
                memo[r][c] = 1
                if (r, c) == (n-1, n-1):
                    return True
                # add neighbors to queue
                for (_r, _c) in neighbors(r, c):
                    queue.append((_r, _c))
            # print(f'{min_dist=}, {memo=}')
            return False

        # print(f'{min_dist_bfs(2)=}')

        lo = 0
        hi = n
        mid = n//2
        prev_mid = None
        while True:
            if mid == prev_mid:
                if min_dist_bfs(mid+1):
                    return mid+1
                else:
                    return mid
            prev_mid = mid
            if min_dist_bfs(mid):
                lo, mid = mid, (mid + hi)//2
            else:
                mid, hi = (lo + mid)//2, mid

class Solution:
    def numRollsToTarget(self, n: int, k: int, target: int) -> int:
        MOD = 10**9+7
        dp = {}
        def helper(dice_left, sum_so_far):
            if dice_left == 1:
                if sum_so_far < target-k:
                    return 0
                else:
                    return 1
            if (dice_left, sum_so_far) in dp:
                return dp[dice_left, sum_so_far]
            total = 0
            for i in range(1, min(k+1, target-sum_so_far)):
                total += helper(dice_left-1, sum_so_far+i)
                total %= MOD
            dp[dice_left, sum_so_far] = total
            return total
        return helper(n, 0)

