class Solution:
    def removeLeafNodes(self, root: Optional[TreeNode], target: int) -> Optional[TreeNode]:
        def helper(root):
            if not root:
                return False
            if not helper(root.left):
                root.left = None
            if not helper(root.right):
                root.right = None
            # children have been deleted or never existed
            if not (root.left or root.right):
                if root.val == target:
                    return False
            return True
        if helper(root):
            return root
        return None

