class Solution:
    def maximumValueSum(self, nums: List[int], k: int, edges: List[List[int]]) -> int:
        total = sum(nums)
        delta = sorted([(num ^ k) - num for num in nums], reverse=True)
        pairs = [delta[i:i+2] for i in range(0, len(delta)//2*2, 2)]
        index = len(pairs) - 1
        while index >= 0 and sum(pairs[index]) < 0: index -= 1
        if index == -1: return total
        return total + sum(sum(pair) for pair in pairs[:index+1])

