# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def countNodes(self, root: Optional[TreeNode]) -> int:
        def height(root: Optional[TreeNode]) -> int:
            if not root: return 0
            return 1 + height(root.left)
        h = height(root)
        if h <= 1: return h
        def found(mid):
            b = bin(mid)[2:]
            b = '0' * ((h-1) - len(b)) + b + 'X'
            # print('mid,b,len(b) =', mid, b, len(b))
            ptr = root
            h_acc = 0
            while ptr:
                # print('ptr.val,h_acc =', ptr.val, h_acc)
                c = b[h_acc]
                if c == '1':
                    ptr = ptr.right
                else:
                    ptr = ptr.left
                h_acc += 1
            return h_acc == h
        def ans(mid):
            complete_nodes = (1 << h) - 1
            complete_last_level_nodes = (1 << h-1)
            # print(f'{complete_nodes=}')
            # print(f'{complete_last_level_nodes=}')
            # print(f'{mid=}')
            return complete_nodes - (complete_last_level_nodes - mid - 1)
        l, r = 0, (1<<h-1)-1
        mid = (l + r)//2
        # print('l,r =', l,r)
        prev = -1
        while True:
            if mid == prev:
                # print('mid=prev=',mid)
                if found(mid):
                    # print('found at mid')
                    if mid < (1<<h-1)-1 and found(mid+1):
                        # print('found mid+1=',mid+1)
                        return ans(mid+1)
                    else:
                        # print('didn\'t find mid+1=',mid+1)
                        return ans(mid)
                else:
                    # print('not found at mid')
                    if mid > 0 and found(mid-1):
                        # print('found mid-1=', mid-1)
                        return ans(mid-1)
                    else:
                        # print('didn\'t find mid-1=', mid-1)
                        return ans(mid)
            if found(mid):
                # print(f'found at mid={mid}, setting l=mid')
                l = mid
            else:
                # print(f'not found at mid={mid}, setting r=mid')
                r = mid
            prev, mid = mid, (l+r)//2

class MyStack:

    def __init__(self):
        self.queue = deque()

    def push(self, x: int) -> None:
        # O(n)
        size = len(self.queue)
        self.queue.append(x)
        for _ in range(size):
            self.queue.append(self.queue.popleft())

    def pop(self) -> int:
        # O(1)
        return self.queue.popleft()

    def top(self) -> int:
        # O(1)
        return self.queue[0]

    def empty(self) -> bool:
        # O(1)
        return not self.queue


