class Solution:
    def reverseVowels(self, s: str) -> str:
        vowels = set('aeiou')
        stack = []
        indices = set()
        for i,c in enumerate(s):
            if c.lower() in vowels:
                indices.add(i)
                stack.append(c)
        out = ''
        for i,c in enumerate(s):
            if i in indices:
                out += stack.pop()
            else:
                out += c
        return out

