class Solution:
    def readBinaryWatch(self, turnedOn: int) -> List[str]:
        def pad2(s):
            if len(s) == 1: return '0' + s
            return s
        d = [8, 4, 2, 1, 32, 16, 8, 4, 2, 1]
        out = []
        for c in combinations(range(10), turnedOn):
            c = set(c)
            hours, minutes = 0, 0
            for x in c:
                if x < 4:
                    hours += d[x]
                else:
                    minutes += d[x]
            if hours > 11 or minutes > 59: continue
            time = '{}:{}'.format(hours, pad2(str(minutes)))
            out.append(time)
        return out

