class Solution:
    def addStrings(self, num1: str, num2: str) -> str:
        carry = 0
        num1, num2 = num1[::-1], num2[::-1]
        idx = 0
        out = ''
        while idx < max(len(num1), len(num2)) or carry > 0:
            s = carry
            if idx < len(num1):
                s += int(num1[idx])
            if idx < len(num2):
                s += int(num2[idx])
            if s >= 10:
                s, carry = s-10, 1
            else:
                carry = 0
            out += str(s)
            idx += 1
        return out[::-1]

