class Solution:
    def imageSmoother(self, img: List[List[int]]) -> List[List[int]]:
        def smooth(r, c):
            total = img[r][c]
            count = 1
            if r > 0:
                total += img[r-1][c]; count += 1
                if c > 0: total += img[r-1][c-1]; count += 1
                if c < len(img[0])-1: total += img[r-1][c+1]; count += 1
            if r < len(img)-1:
                total += img[r+1][c]; count += 1
                if c > 0: total += img[r+1][c-1]; count += 1
                if c < len(img[0])-1: total += img[r+1][c+1]; count += 1
            if c > 0: total += img[r][c-1]; count += 1
            if c < len(img[0])-1: total += img[r][c+1]; count += 1
            return total // count
        out = [[0 for _ in range(len(img[0]))]
                  for _ in range(len(img))]
        for r in range(len(img)):
            for c in range(len(img[0])):
                out[r][c] = smooth(r, c)
        return out

