class Solution:
    def findSecondMinimumValue(self, root: Optional[TreeNode]) -> int:
        if not root: return -1
        def dfs(root, rootval):
            if not root: return -1
            if root.val != rootval:
                return root.val
            l = dfs(root.left, rootval)
            r = dfs(root.right, rootval)
            if l == r == -1:
                return rootval
            if l == r == rootval:
                return rootval
            if l != rootval and r != rootval:
                return min(l,r)
            if l == rootval or r == rootval:
                return max(l,r)
        out = dfs(root, root.val)
        if out == root.val: return -1
        return out

