    def validPalindrome(self, s: str) -> bool:
        l, r = 0, len(s)-1
        def isvalid(l, r, used):
            if l >= r: return True
            if s[l] != s[r]:
                if used: return False
                return isvalid(l, r-1, True) or isvalid(l+1, r, True)
            else:
                return isvalid(l+1, r-1, used)
        return isvalid(l, r, False)

