class Solution:
    def countBinarySubstrings(self, s: str) -> int:
        def find_all(s, substring):
            out = []
            i = 0
            while True:
                loc = s.find(substring, i)
                if loc == -1:
                    break
                out.append(loc)
                i = loc + 1
            return out
        def expansion_distance(loc, substring):
            l, r = loc, loc+1
            total = 0
            while l >= 0 and r < len(s) and s[l] == substring[0] and s[r] == substring[1]:
                l -= 1
                r += 1
                total += 1
            return total
        aloc = find_all(s, '01')
        bloc = find_all(s, '10')
        total = 0
        for loc in aloc:
            total += expansion_distance(loc, '01')
        for loc in bloc:
            total += expansion_distance(loc, '10')
        return total

class Solution:
    def findShortestSubArray(self, nums: List[int]) -> int:
        c = Counter(nums)
        degree = max(c.values())
        if degree == 1:
            return 1
        choices = {}
        for k,v in c.items():
            if v < degree: continue
            choices[k] = (1e300, -1e300)
        for i,e in enumerate(nums):
            if e in choices:
                x,y = choices[e]
                choices[e] = min(x,i), max(y,i)
        best = 1e300
        for x,y in choices.values():
            best = min(best, y-x)
        return best + 1

