        def dfs(r, c, s):
            if image[r][c] == color:
                return
            if image[r][c] != s:
                return
            image[r][c] = color
            if r > 0: dfs(r-1, c, s)
            if r < len(image)-1: dfs(r+1, c, s)
            if c > 0: dfs(r, c-1, s)
            if c < len(image[0])-1: dfs(r, c+1, s)
        dfs(sr, sc, image[sr][sc])
        return image

