            while r < len(matrix)-1 and c < len(matrix[0])-1:
                r += 1
                c += 1
                if matrix[r][c] != val: return False
            return True
        diags = []
        diags += [(0, c) for c in range(len(matrix[0]))]
        diags += [(r, 0) for r in range(1,len(matrix))]
        return all(valid(*diag) for diag in diags)

