class Solution:
    def search(self, nums: List[int], target: int) -> int:
        l, r = 0, len(nums)-1
        mid = (l + r)//2
        prev = -1
        while True:
            if prev == mid: return -1
            if nums[mid] < target:
                l = mid + 1
            elif nums[mid] > target:
                r = mid
            else:
                return mid
            prev, mid = mid, (l + r)//2

