import operator
class Solution:
    def subsetXORSum(self, nums: List[int]) -> int:
        total = 0
        for i in range(1<<len(nums)):
            b = bin(i)[2:]
            b = '0' * (len(nums)-len(b)) + b
            if not '1' in b:
                continue
            total += reduce(
                operator.xor,
                (e for j,e in enumerate(nums) if b[j] == '1')
            )
        return total

