import random

class Node:
    def __init__(self, val):
        self.val = val
        self.left = None
        self.right = None

class MyHashSet:

    def __init__(self):
        self.root = None

    def _add_helper(self, root, val):
        if root is None:
            return Node(val)
        if val < root.val:
            root.left = self._add_helper(root.left, val)
        elif val > root.val:
            root.right = self._add_helper(root.right, val)
        # if val == root.val, do nothing
        return root

    def add(self, key: int) -> None:
        self.root = self._add_helper(self.root, key)

    def _remove_helper(self, root, val):
        if root is None:
            return root
        if val > root.val:
            root.right = self._remove_helper(root.right, val)
        elif val < root.val:
            root.left = self._remove_helper(root.left, val)
        else:
            if root.left is None:
                return root.right
            if root.right is None:
                return root.left

            if random.random() < 0.5:
                # Find the minimum value in the right subtree
                ptr = root.right
                while ptr.left:
                    ptr = ptr.left
                root.val = ptr.val
                root.right = self._remove_helper(root.right, root.val)
            else:
                # Find the maximum value in the left subtree
                ptr = root.left
                while ptr.right:
                    ptr = ptr.right
                root.val = ptr.val
                root.left = self._remove_helper(root.left, root.val)
        return root

    def remove(self, key: int) -> None:
        self.root = self._remove_helper(self.root, key)

    def _contains_helper(self, root, val):
        if root is None:
            return False
        if val < root.val:
            return self._contains_helper(root.left, val)
        if val > root.val:
            return self._contains_helper(root.right, val)
        return True

    def contains(self, key: int) -> bool:
        return self._contains_helper(self.root, key)

