class TrieNode:
    def __init__(self):
        self.children = [None] * 10
        self.is_end_of_number = False
        self.num_children = 0

    def has_child(self, s):
        return self.children[int(s)] is not None

    def get_child(self, s):
        return self.children[int(s)]

    def set_child(self, s, value):
        already_had = self.has_child(s)
        self.children[int(s)] = value
        if not already_had:
            self.num_children += 1

    def del_child(self, s):
        already_had = self.has_child(s)
        self.children[int(s)] = None
        if already_had:
            self.num_children -= 1

