from math import atan2

def det2(mat):
    # determinant of 2x2 mat
    return mat[0][0] * mat[1][1] - mat[0][1] * mat[1][0]

def det3(mat):
    # determinant of 3x3 mat
    a, b, c = mat[0]
    d, e, f = mat[1]
    g, h, i = mat[2]
    return a*(e*i - f*h) - b*(d*i - g*f) + c*(d*h - e*g)

def angle(p1, p2):
    return atan2(p2[1]-p1[1], p2[0]-p1[0])

def ccw_order_around_center(points):
    # take average of points to get point in center of polygon
    mid = (sum(p[0] for p in points)/4.0, sum(p[1] for p in points)/4.0)
    return sorted(points, key=lambda p:angle(mid, p))

def area_of_polygon(points):
    ordered = ccw_order_around_center(points)
    detsum = 0
    for a,b in pairwise(ordered + [ordered[0]]):
        mat = list(zip(a,b))
        detsum += det2(mat)
    return detsum/2.0

