def ccw(a, b, c):
    # return true if angle abc is ccw, otherwise false
    # if in a line, also false, as det3 is 0
    x1, y1 = a
    x2, y2 = b
    x3, y3 = c
    return det3([
        [x1, y1, 1],
        [x2, y2, 1],
        [x3, y3, 1]
    ]) > 0

