def max_area_triangle(convex_points):
    # https://arxiv.org/abs/1705.11035
    def area_by_indices(x,y,z):
        return area_of_polygon([convex_points[i] for i in (x,y,z)])
    n = len(convex_points)
    a = 0
    b = 1
    c = 2
    m = area_by_indices(a, b, c)
    best = (a, b, c)
    while True:
        while c != a:
            while area_by_indices(a, b, (c+1) % n) >= area_by_indices(a, b, c):
                c = (c+1) % n
            if area_by_indices(a, b, c) <= area_by_indices(a, (b+1) % n, c):
                b = (b+1) % n
                continue
            else:
                break
        if (candidate := area_by_indices(a, b, c)) > m:
            m = candidate
            best = (a, b, c)
        a = (a+1) % n
        b = (a+1) % n
        c = (a+2) % n
        if a == 0:
            break
    return m, best

