        self.dp = {}
        def dfs(substring):
            if not substring:
                return [[]]
            if substring in self.dp:
                return self.dp[substring]
            out = []
            for index in range(1, len(substring)+1):
                candidate = substring[:index]
                if candidate == candidate[::-1]:
                    for suffix in dfs(substring[index:]):
                        out.append([substring[:index]] + suffix)
            self.dp[substring] = out
            return out
        return dfs(s)

