    for n in L:x[n%k][n]+=1
    for s in x:
        v,p,c,a,b=x[s],-k,1,1,0
        for n in sorted(v):f=v[n];c=a+((1<<f)-1)*(a if n-p-k else b);b,a,p=a,c,n
