class Solution:
    def maxScoreWords(self, words: List[str], letters: List[str], score: List[int]) -> int:
        # calculate and attach score to each word
        word_scores = []
        for word in words:
            word_score = 0
            c = Counter(word)
            for k,v in c.items():
                word_score += score[ord(k)-ord('a')] * v
            word_scores.append((word,c,word_score))
        # iterate through words (dp):
        # dp takes two params - index in words, and letters remaining
        def letter_counts_to_unique_rep(c):
            return tuple(sorted(c.items()))
        dp = {}
        def helper(index, letters_remaining):
            key = (index, letter_counts_to_unique_rep(letters_remaining))
            if key in dp:
                return dp[key]
            # base case
            if index >= len(word_scores):
                return 0
            word, word_letter_counts, word_score = word_scores[index]
            best = -1
            if letters_remaining >= word_letter_counts:
                # consider taking word if possible
                best = word_score + helper(index+1, letters_remaining-word_letter_counts)
            # consider not taking word
            best = max(best, helper(index+1, letters_remaining))
            dp[key] = best
            return best

        return helper(0, Counter(letters))

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> List[str]:
        self.max_len = len(max(wordDict, key=len))
        self.valid = set(wordDict)
        self.out = set()
        self.dp = set()
        self.s = s
        # print(f'''
        #     {self.max_len=}
        #     {self.valid=}
        #     {self.out=}
        #     {self.dp=}
        #     {self.s=}
        # ''')
        # self.iters = 0
        def helper(word_list_so_far, index, s_remaining):
            # self.iters += 1
            # no words of this length or greater
            if index > self.max_len:
                return
            # determine whether or not to insert a space (or if already seen)
            key = (word_list_so_far, index, s_remaining)
            if key in self.dp:
                return # already processing
            if not s_remaining: # or index >= len(s_remaining):
                self.out.add(word_list_so_far.strip())
                return # no further processing needed
            # check whether adding a space would create a valid word
            word_so_far = s_remaining[:index]
            # print(f'{word_so_far=}')
            if word_so_far in self.valid:
                # if so, consider adding a space here
                helper(
                    word_list_so_far.strip() + ' ' + s_remaining[:index],
                    0,
                    s_remaining[index:]
                )
            helper(
                word_list_so_far,
                index+1,
                s_remaining
            )
            self.dp.add(key)
        helper('', 0, s)
        # print(f'{self.iters=}')
        return self.out

