            return len(nums)
        if nums[-1] == len(nums)-1:
            return nums[-1]
        for idx,(i,j) in enumerate(pairwise(nums + [-1])):
            # print(idx, i, j)
            while i > j:
                # print(i)
                if i == idx + 1:
                    return i
                i -= 1
        return -1

class Solution:
    def equalSubstring(self, s: str, t: str, maxCost: int) -> int:
        l, r, best = 0, 0, 0
        cost = lambda i : abs(ord(s[i])-ord(t[i]))
        c = 0
        while r < len(s):
            c += cost(r)
            while c > maxCost and l <= r:
                c -= cost(l)
                l += 1
            best = max(best, r - l + 1)
            r += 1
        return best

