class Solution:
    def numSteps(self, s: str) -> int:
        s = s.lstrip('0')
        if len(s) == 1: return 0
        l = list(s)
        num_zeroes = s.count('0')
        steps = 0
        while len(l) > 1:
            # print(''.join(l))
            if l[-1] == '0':
                l.pop()
                num_zeroes -= 1
            else:
                if num_zeroes == 0:
                    return steps + len(l) + 1
                else:
                    for i in range(len(l)-1, -1, -1):
                        if l[i] == '1':
                            l[i] = '0'
                            num_zeroes += 1
                        else:
                            l[i] = '1'
                            num_zeroes -= 1
                            break
            steps += 1
        return steps

