class Solution:
    def findIntegers(self, n: int) -> int:
        dp = [0] * 32
        dp[0] = 1
        dp[1] = 2
        for i in range(2, len(dp)):
            dp[i] = dp[i-1] + dp[i-2]
        total = prev_bit = 0
        i = 30
        while i >= 0:
            if (n & (1<<i)):
                total += dp[i]
                if prev_bit:
                    total -= 1
                    break
                prev_bit = 1
            else:
                prev_bit = 0
            i -= 1
        return total + 1

class Solution:
    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        trie = {}
        def addWord(word):
            root = trie
            idx = 0
            while idx < len(word):
                if word[idx] not in root:
                    root[word[idx]] = {}
                    root = root[word[idx]]
                else:
                    root = root[word[idx]]
                idx += 1
            # end of word marker
            root['END'] = None
        def firstContainedWord(word):
            root = trie
            idx = 0
            while root and idx < len(word):
                if 'END' in root:
                    return word[:idx]
                if word[idx] not in root:
                    return False
                root = root[word[idx]]
                idx += 1
            if 'END' in root:
                return word[:idx]
            return False
        for word in dictionary:
            addWord(word)
        split = sentence.split()
        out = []
        for word in split:
            first = firstContainedWord(word)
            if first:
                out.append(first)
            else:
                out.append(word)
        return ' '.join(out)

