class Solution:
    def canFinish(self, numCourses: int, prerequisites: List[List[int]]) -> bool:
        # topo sort - pop elements with zero in-edges until there are none left
        # if any elements remain, return false; otherwise, return true
        nodes = [Node(i) for i in range(numCourses)]
        for a,b in prerequisites:
            nodes[a].outs.add(nodes[b])
            nodes[b].ins.add(nodes[a])
        total = 0
        frontier = {node for node in nodes if not node.ins}
        while frontier:
            new_frontier = set()
            for node in frontier:
                for neighbor in node.outs:
                    neighbor.ins.remove(node)
                    if not neighbor.ins:
                        new_frontier.add(neighbor)
                total += 1
            frontier = new_frontier
        return total == numCourses

