class Solution:
    def findOrder(self, numCourses: int, prerequisites: List[List[int]]) -> List[int]:
        # topo sort - pop elements with zero in-edges until there are none left
        # if any elements remain, return empty list; otherwise, return list of courses popped
        nodes = [Node(i) for i in range(numCourses)]
        for a,b in prerequisites:
            nodes[a].ins.add(nodes[b])
            nodes[b].outs.add(nodes[a])
        ordering = []
        frontier = {node for node in nodes if not node.ins}
        while frontier:
            new_frontier = set()
            for node in frontier:
                for neighbor in node.outs:
                    neighbor.ins.remove(node)
                    if not neighbor.ins:
                        new_frontier.add(neighbor)
                ordering.append(node.val)
            frontier = new_frontier
        if len(ordering) == numCourses:
            return ordering
        return []

