class Solution:
    def rightSideView(self, root: Optional[TreeNode]) -> List[int]:
        # order by depth, then by number of rights
        # (where rights are weighted by depth)
        self.depths = {}
        def dfs(root, depth=0, rights=0):
            if not root: return
            if depth in self.depths:
                _, best = self.depths[depth]
                if best < rights:
                    self.depths[depth] = root.val, rights
            else:
                self.depths[depth] = root.val, rights
            dfs(root.left, depth+1, rights-2**(-depth))
            dfs(root.right, depth+1, rights+2**(-depth))
        dfs(root)
        return [x[0] for _,x in sorted(self.depths.items())]

class Solution:
    def gameOfLife(self, board: List[List[int]]) -> None:
        """
        Do not return anything, modify board in-place instead.
        """
        def neighbors(i,j):
            out = 0
            if i > 0:
                out += board[i-1][j]
                if j > 0: out += board[i-1][j-1]
                if j < len(board[0])-1: out += board[i-1][j+1]
            if i < len(board)-1:
                out += board[i+1][j]
                if j > 0: out += board[i+1][j-1]
                if j < len(board[0])-1: out += board[i+1][j+1]
            if j > 0: out += board[i][j-1]
            if j < len(board[0])-1: out += board[i][j+1]
            return out
        out = [[0] * len(board[0]) for _ in range(len(board))]
        for i in range(len(board)):
            for j in range(len(board[0])):
                n = neighbors(i, j)
                if not board[i][j]:
                    if n == 3:
                        out[i][j] = 1
                elif n in (2,3):
                    out[i][j] = 1
        for i in range(len(board)):
            for j in range(len(board[0])):
                board[i][j] = out[i][j]

