class Solution:
    def canJump(self, nums: List[int]) -> bool:
        if len(nums) == 1: return True
        dp = [0] * (len(nums)-1) + [2]
        def helper(i):
            if dp[i] > 0:
                return dp[i]
            if nums[i] == 0:
                return 1
            out = 1
            for choice in range(i+1, min(i+nums[i]+1,len(nums))):
                if helper(choice) == 2:
                    out = 2
                    break
            dp[i] = out
            return out
        return helper(0) == 2

