class Solution:
    def minPatches(self, nums: List[int], n: int) -> int:
        i = count = x = 0
        # first, fill in gaps between existing coins
        while i < len(nums) and x < n:
            if nums[i] <= x + 1:
                x += nums[i]
                i += 1
            else:
                count += 1
                x = 2 * x + 1
        # next, continue doubling coin size with selective additions
        # inductively, largest generatable will be x -> 2x+1 per step
        while x < n:
            count += 1
            x = 2 * x + 1
        return count

