class Solution:
    def minDays(self, bloomDay: List[int], m: int, k: int) -> int:
        if m * k > len(bloomDay): return -1

        # whether it is possible to make m bouquets on day d
        def valid(d):
            bouquets = 0
            run_length = 0
            for i in bloomDay:
                if i > d:
                    bouquets += run_length // k
                    if bouquets >= m: return True
                    run_length = 0
                else:
                    run_length += 1
            bouquets += run_length // k
            return bouquets >= m

        day_range = sorted(bloomDay)
        d = bisect_left(day_range, 0.5, key=valid)

        return day_range[d]

