class Solution:
    def shipWithinDays(self, weights: List[int], days: int) -> int:
        # binary search on weight capacity of ship
        max_cap = max(weights)
        def valid(capacity):
            run_sum = 0
            total_days = 0
            for w in weights:
                if run_sum + w > capacity:
                    total_days += 1
                    run_sum = w
                    if total_days > days:
                        return False
                else:
                    run_sum += w
            return total_days + 1 <= days

        # too memory hungry
        # capacity_range = list(range(max_cap, sum(weights)+1))

        # ALWAYS prefer using bisect_left to writing binary search by hand
        # this is Python after all
        capacity_range = FakeList(max_cap, sum(weights))

        c = bisect_left(capacity_range, 0.5, key=valid)
        # print(c, capacity_range)
        return capacity_range[c]

class Solution:
    def singleNumber(self, nums: List[int]) -> int:
        # bit storage
        single = 0
        double = 0
        # remove bits in b from a
        remove = lambda a,b : a & (a ^ b)
        for n in nums:
            if n < 0:
                n = -n
                n <<= 32
            triple = (n & double)
            double |= (n & single)
            single = remove(n | single, double)
            single = remove(single, triple)
            double = remove(double, triple)
        if single and single >> 32:
            return -(single >> 32)
        return single

