class Solution:
    def countLatticePoints(self, circles: List[List[int]]) -> int:
        # idea - start with lattice points contained in rectangle area
        # and then check whether each point is actually contained in the circle
        lattice_points = set()
        def get_lattice_points(circle):
            # largest integer square inside circle will definitely have points
            # contained inside the circle itself, no need to check
            # divide radius by sqrt(2) to get max int square radial distance
            x, y, r = circle
            d = r // (2**0.5)
            out = []
            # check every point in bounding rect
            # if inside inner square, just add it
            # otherwise need to verify point within circle
            for _x in range(x-r, x+r+1):
                for _y in range(y-r, y+r+1):
                    if x-d <= _x <= x+d and y-d <= _y <= y+d:
                        out.append((_x, _y))
                    elif ((_x-x)**2 + (_y-y)**2)**0.5 <= r:
                        out.append((_x, _y))
            return set(out)

        for circle in circles:
            lattice_points |= get_lattice_points(circle)
        return len(lattice_points)

