class Solution:
    def minKBitFlips(self, nums: List[int], k: int) -> int:
        curr_flips = total_flips = 0
        for i in range(len(nums)):
            # no longer in previous flip radius
            if i >= k and nums[i-k] == 2:
                curr_flips -= 1
            # current index requires a flip
            if curr_flips % 2 == nums[i]:
                # required flip extends beyond max range
                if i + k > len(nums):
                    return -1
                # mark current index as flipped
                nums[i] = 2
                curr_flips += 1
                total_flips += 1
        return total_flips

