class Solution:
    def bulbSwitch(self, n: int) -> int:
        # only perfect squares s have an odd number of factors,
        # as they have a factor f for which f * f = s,
        # rather than only pairs of factors a, b so that the
        # number of factors of s is of the form 2k+1 rather than
        # 2k for some integer k
        # therefore, we can just return the number of perfect 
        # squares less than or equal to n (that is, floor(sqrt(n)))
        return int(n**0.5)

