class Solution:
    def nextPermutation(self, nums: List[int]) -> None:
        """
        Do not return anything, modify nums in-place instead.
        """
        # https://en.m.wikipedia.org/wiki/Permutation#Generation_in_lexicographic_order
        for k in range(len(nums)-2,-1,-1):
            if nums[k] < nums[k+1]:
                break
        else:
            nums.reverse()
            return
        for l in range(len(nums)-1,k,-1):
            if nums[k] < nums[l]:
                break
        else:
            raise ValueError('unexpected successful loop termination')
        nums[k], nums[l] = nums[l], nums[k]
        nums[k+1:] = nums[k+1:][::-1]
        return

