    def searchRange(self, nums: List[int], target: int) -> List[int]:
        if not nums: return [-1, -1]
        l, r = bisect_left(nums, target), bisect_right(nums, target)
        if (r == len(nums) and nums[-1] != target) or nums[l] != target:
            return [-1, -1]
        return [l, r-1]

class Solution:
    def maxSubArray(self, nums: List[int]) -> int:
        best = -float('inf')
        curr = 0
        for n in nums:
            curr = max(n, curr + n)
            best = max(best, curr)
        return best

class Solution:
    def getAncestors(self, n: int, edges: List[List[int]]) -> List[List[int]]:
        # swap edge directions into adj list of in-edges
        adj_in = [set() for _ in range(n)]
        for i,j in edges:
            adj_in[j].add(i)
        # dp ancestor retrieval
        toplevel = {node for node,parents in enumerate(adj_in) if not parents}
        out = [None] * n
        for node in toplevel:
            out[node] = set()
        def retrieve_ancestors(node):
            if out[node] is not None:
                return out[node]
            parents = adj_in[node]
            ancestors = parents.copy()
            for parent in parents:
                ancestors |= retrieve_ancestors(parent)
            out[node] = ancestors
            return out[node]
        for node in range(n):
            retrieve_ancestors(node)
        return [sorted(ancestors) for ancestors in out]

class Solution:
    def maxNumEdgesToRemove(self, n: int, edges: List[List[int]]) -> int:
        self.parent = list(range(n+1))
        self.size = [1] * (n+1)
        def union(i, j):
            i, j = find(i), find(j)
            # can remove this edge as already connected
            if i == j: return False
            if self.size[i] > self.size[j]:
                self.parent[j] = i
                self.size[i] += self.size[j]
            else:
                self.parent[i] = j
                self.size[j] += self.size[i]
            # no edge removable - add to both counts
            return True
        def find(i):
            while i != self.parent[i]:
                i = self.parent[i]
            return i
        removable = 0
        type1 = type2 = 0

        # alice and bob (type 3)
        for edgetype, i, j in edges:
            if edgetype == 3:
                if union(i, j):
                    type1 += 1
                    type2 += 1
                else:
                    removable += 1
        # copy so that can be used for bob later
        parent_tmp = self.parent.copy()

        # alice only (type 1)
        for edgetype, i, j in edges:
            if edgetype == 1:
                if union(i, j):
                    type1 += 1
                else:
                    removable += 1

        # bob only (type 2)
        self.parent = parent_tmp
        for edgetype, i, j in edges:
            if edgetype == 2:
                if union(i, j):
                    type2 += 1
                else:
                    removable += 1

        # unable to create msts (# edges = n-1) for both alice and bob
        if not (type1 == type2 == n-1): return -1
        return removable

