class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def dfs(root):
            if not root: return None
            subtree_min, subtree_max = root.val, root.val
            left = dfs(root.left)
            if left is not None:
                left_min, left_max = left
                if left_max >= root.val:
                    raise Exception
                subtree_min = left_min
            right = dfs(root.right)
            if right is not None:
                right_min, right_max = right
                if right_min <= root.val:
                    raise Exception
                subtree_max = right_max
            return subtree_min, subtree_max

        try:
            dfs(root)
            return True
        except Exception as e:
            print(repr(e))
            return False

import re
class Solution:
    def simplifyPath(self, path: str) -> str:
        # print(path)
        path = re.sub(r'/+', '/', path)
        # print(path)
        path = path.rstrip('/')
        # print(path)
        directories = path.split('/')[1:]
        # print(directories)
        stack = []
        for d in directories:
            if d == '.':
                continue
            elif d == '..':
                if stack:
                    stack.pop()
            else:
                stack.append(d)
        # print(stack)
        return '/' + '/'.join(stack)

class Solution:
    def threeConsecutiveOdds(self, arr: List[int]) -> bool:
        seen = 0
        for i in arr:
            if i % 2:
                seen += 1
                if seen == 3:
                    return True
            else:
                seen = 0
        return seen == 3

# Definition for singly-linked list.
# class ListNode:
#     def __init__(self, val=0, next=None):
#         self.val = val
#         self.next = next
class Solution:
    def mergeNodes(self, head: Optional[ListNode]) -> Optional[ListNode]:
        # remove leading zeros
        while head and not head.val:
            head = head.next
        # sum groups between zeros
        ptr = head
        while ptr:
            if ptr.val:
                while ptr.next and ptr.next.val:
                    ptr.val += ptr.next.val
                    ptr.next = ptr.next.next
            ptr = ptr.next
        # remove intermediate zeros
        ptr = head
        while ptr:
            while ptr.next and not ptr.next.val:
                ptr.next = ptr.next.next
            ptr = ptr.next
        return head

class Solution:
    def passThePillow(self, n: int, time: int) -> int:
        d, r = divmod(time, n-1)
        return n - r if d % 2 else 1 + r

class Solution:
    def passThePillow(self, n: int, time: int) -> int:
        location = 1
        right = True
        for _ in range(time):
            if right:
                location += 1
                if location == n:
                    right = False
            else:
                location -= 1
                if location == 1:
                    right = True
        return location

class Solution:
    def numWaterBottles(self, numBottles: int, numExchange: int) -> int:
        consumed = 0
        numEmpty = 0
        while numBottles:
            consumed += numBottles
            numEmpty += numBottles
            exchanged, numEmpty = divmod(numEmpty, numExchange)
            numBottles = exchanged
        return consumed

class Solution:
    def averageWaitingTime(self, customers: List[List[int]]) -> float:
        customers.reverse()
        n = len(customers)
        t = customers[-1][0]
        total = 0
        while customers:
            arrival, preptime = customers.pop()
            if arrival > t:
                t = arrival + preptime
            else:
                t += preptime
            total += t - arrival
        return total/n

