class Solution:
    def reverseParentheses(self, s: str) -> str:
        stack = []
        for c in s:
            if c == '(':
                stack.append(c)
            elif c == ')':
                temp_stack = []
                while stack[-1] != '(':
                    temp_stack.append(stack.pop())
                stack.pop()
                stack += temp_stack
            else:
                stack.append(c)
        return ''.join(stack)

class Solution:
    def maximumGain(self, s: str, x: int, y: int) -> int:
        num_a = num_b = out = 0
        worse = min(x,y)
        for c in s:
            if c > 'b':
                out += min(num_a, num_b) * worse
                num_a = num_b = 0
            elif c == 'a':
                if x < y and num_b > 0:
                    num_b -= 1
                    out += y
                else:
                    num_a += 1
            elif c == 'b':
                if x > y and num_a > 0:
                    num_a -= 1
                    out += x
                else:
                    num_b += 1
        return out + min(num_a, num_b) * worse

class Solution:
    def survivedRobotsHealths(self, positions: List[int], healths: List[int], directions: str) -> List[int]:
        n = len(positions)
        robots = [[p, h, d, i] for i,(p,h,d) in enumerate(zip(positions, healths, directions))]
        robots.sort(key=lambda x:x[0])
        stack = []
        for p, h, d, i in robots:
            if d == 'R' or not stack:
                stack.append([p,h,d,i])
            else:
                add = True
                while stack and stack[-1][2] == 'R' and add:
                    last_health = stack[-1][1]
                    if h > last_health:
                        stack.pop()
                        h -= 1
                    elif h < last_health:
                        stack[-1][1] -= 1
                        add = False
                    else:
                        stack.pop()
                        add = False
                if add:
                    stack.append([p,h,d,i])
        return [h for _,h,_,_ in sorted(stack, key=lambda x:x[3])]

class Solution:
    def countOfAtoms(self, formula: str) -> str:
        prev = None
        stack = []
        idx = 0
        while idx < len(formula):
            c = formula[idx]
            if c.isalpha():
                if c.lower() == c:
                    # part of element notation
                    stack[-1] += c
                else:
                    # new element
                    stack.append(c)
            elif c.isnumeric():
                # turn atom into dict from element to count
                i = c
                idx += 1
                while idx < len(formula) and formula[idx].isnumeric():
                    print(formula[idx],i,idx)
                    i += formula[idx]
                    idx += 1
                ct = int(i)
                if type(stack[-1]) == dict:
                    for k in stack[-1]:
                        stack[-1][k] *= ct
                elif type(stack[-1]) == str:
                    stack[-1] = (stack[-1],ct)
                continue
            elif c == '(':
                stack.append('(')
            elif c == ')':
                d = {}
                while stack[-1] != '(':
                    e = stack.pop()
                    if type(e) == tuple:
                        x, ct = e
                        if x not in d:
                            d[x] = ct
                        else:
                            d[x] += ct
                    elif type(e) == str:
                        if e not in d:
                            d[e] = 1
                        else:
                            d[e] += 1
                    elif type(e) == dict:
                        for k,v in e.items():
                            if k in d:
                                d[k] += v
                            else:
                                d[k] = v
                    else:
                        raise TypeError('got type {}'.format(type(e)))
                stack.pop() # remove '('
                stack.append(d)
            idx += 1
        print(stack)
        # merge stack one final time
        d = {}
        for e in stack:
            if type(e) == dict:
                for k,v in e.items():
                    if k in d:
                        d[k] += v
                    else:
                        d[k] = v
            elif type(e) == str:
                if e in d:
                    d[e] += 1
                else:
                    d[e] = 1
            elif type(e) == tuple:
                x, ct = e
                if x in d:
                    d[x] += ct
                else:
                    d[x] = ct
        s = ''.join(x+str(ct) if ct > 1 else x for x,ct in sorted(d.items()))
        return s

# Definition for a binary tree node.
# class TreeNode:
#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def getDirections(self, root: Optional[TreeNode], startValue: int, destValue: int) -> str:
        self.ps = ''
        self.pd = ''
        self.p = []
        def dfs(root):
            if not root: return
            if root.val == startValue:
                self.ps = ''.join(self.p)
            elif root.val == destValue:
                self.pd = ''.join(self.p)
            if self.ps and self.pd:
                return
            self.p.append('L')
            dfs(root.left)
            self.p.pop()
            self.p.append('R')
            dfs(root.right)
            self.p.pop()
        dfs(root)
        common = 0
        s_shorter = len(self.ps) < len(self.pd)
        minlength = min(len(self.ps), len(self.pd))
        for i in range(minlength):
            if self.ps[i] == self.pd[i]:
                common += 1
            else:
                break
        # print(self.ps, self.pd, common)
        if minlength == common:
            # one is the ancestor of another
            if s_shorter:
                # source is the ancestor of dest
                return self.pd[len(self.ps):]
            else:
                # dest is the ancestor of source
                return 'U' * (len(self.ps) - len(self.pd))
        else:
            # share an ancestor that is not either
            return 'U' * (len(self.ps)-common) + self.pd[common:]

class Solution:
    def createBinaryTree(self, descriptions: list[list[int]]) -> Optional[TreeNode]:
        adj = {}
        all_children = set()
        for parent, child, isleft in descriptions:
            all_children.add(child)
            if parent in adj:
                adj[parent][isleft] = child
            else:
                adj[parent] = [0,0]
                adj[parent][isleft] = child
        rootval = (set(adj.keys())-all_children).pop()
        root = TreeNode(val=rootval)
        frontier = [root]
        while frontier:
            next_frontier = []
            for node in frontier:
                if node.val in adj:
                    r,l = adj[node.val]
                    if l:
                        l = TreeNode(val=l)
                        node.left = l
                        next_frontier.append(l)
                    if r:
                        r = TreeNode(val=r)
                        node.right = r
                        next_frontier.append(r)
            frontier = next_frontier
        return root

