class Solution:
    def delNodes(self, root: Optional[TreeNode], to_delete: List[int]) -> List[TreeNode]:
        self.out = []
        self.to_delete = set(to_delete)
        def dfs(root, parent, parent_left, parent_deleted):
            if not root: return
            if root.val in self.to_delete:
                if parent and parent_left:
                    parent.left = None
                elif parent:
                    parent.right = None
                dfs(root.left, root, True, True)
                dfs(root.right, root, False, True)
            else:
                if parent_deleted:
                    self.out.append(root)
                dfs(root.left, root, True, False)
                dfs(root.right, root, False, False)

        dfs(root, None, False, True)
        return self.out

