class Solution:
    def countPairs(self, root: TreeNode, distance: int) -> int:
        # impossible to create any length-1 paths
        if distance == 1: return 0

        self.out = 0

        def dfs(root):
            if not root: return [0] * (distance + 1)
            if not root.left and not root.right:
                return [0, 1] + [0] * (distance - 1)
            left = dfs(root.left)
            right = dfs(root.right)
            for l in range(1, len(left)):
                for r in range(distance-1, -1, -1):
                    if l + r <= distance:
                        self.out += left[l] * right[r]
            out = [0] * (distance + 1)
            for i in range(distance-1, 0, -1):
                out[i+1] = left[i] + right[i]
            return out
        dfs(root)
        return self.out

