class Solution:
    def numberOfWays(self, s: str) -> int:
        l0 = [0]
        l1 = [0]
        for i in range(len(s)):
            l0.append(l0[-1] + (s[i] == '0'))
            l1.append(l1[-1] + (s[i] == '1'))
        total = 0
        for i in range(len(s)):
            if s[i] == '0':
                total += (l1[i]) * (l1[-1] - l1[i+1])
            if s[i] == '1':
                total += (l0[i]) * (l0[-1] - l0[i+1])
        return total

